        self.limit = RateLimiter(CHAT_PER_MINUTE)
        self.read_limit = RateLimiter(READS_PER_MINUTE)
        self.new_limit = RateLimiter(NEW_VISITORS_PER_HOUR, window=3600)
        self._live = (0.0, {})
        self.mcp_sessions: OrderedDict[str, dict] = OrderedDict()
