    # ---------------- common ----------------
    def live_counts(self) -> dict:
        """Cache current catalog reachability without persisting a historical claim."""
        now = time.time()
        at, counts = self._live
        if counts and now - at < LIVE_TTL:
            return counts
        rows = self.store.query("""SELECT kind, COUNT(*) AS n FROM resources
            WHERE active=1 AND health_status IN ('healthy','reachable') GROUP BY kind""")
        counts = {r["kind"]: r["n"] for r in rows}
        self._live = (now, counts)
        return counts

    def live_total(self) -> int:
        return sum(self.live_counts().values())

    def _rebuild_bootstrap_snapshot(self) -> dict:
        now = time.time()
        stages = {}
        def measured(name, call):
            started = time.monotonic()
            try:
                return call()
            finally:
                stages[name] = round((time.monotonic() - started) * 1000, 3)
        templates = measured('templates', lambda: get_front_workflow_templates(self.store))
        ready_templates = [t for t in templates if t.get('execution_availability', {}).get('available')]
        default_template = next(
            (t for t in ready_templates if t['name'] == 'Daily Tech News & AI Research Digest'),
            next(iter(ready_templates), next(
                (t for t in templates if t['name'] == 'Daily Tech News & AI Research Digest'),
                next(iter(templates), None))),
        )
        data = {
            "overview": measured('overview', lambda: get_snapshot_overview(self.store)),
            "explore": measured('explore', lambda: get_front_explore(self.store, "", None, None, False, False, 12)),
            "insights": measured('insights', lambda: served_insights(self.store)),
            "workflow_default": default_template,
            "workflow_templates": templates,
            "testbench_presets": list(FRONT_TESTBENCH_PRESETS.values()),
            "testbench_examples": measured('examples', lambda: live_examples(self.store)),
        }
        json_str = json.dumps(data, separators=(",", ":")).replace("<", "\\u003c")
        agents = measured('example_agents', lambda: self._example_agents(data["testbench_examples"]))
        with _bootstrap_snapshot_cache["lock"]:
            _bootstrap_snapshot_cache["data"] = data
            _bootstrap_snapshot_cache["example_agents"] = agents
            _bootstrap_snapshot_cache["json"] = json_str
            _bootstrap_snapshot_cache["store_id"] = id(self.store)
            _bootstrap_snapshot_cache["at"] = now
            _bootstrap_snapshot_cache["revalidating"] = False
            self._bootstrap_timings_ms = stages
        return data

    def _example_agents(self, examples) -> dict:
        """Connection details for the Test page's examples, so a new example opens without a request.

        Kept beside the bootstrap data (not in it: the home page never sends them) and looked up
        again only when the example set changes.
        """
        from .pearl_view import TEST_AGENT_FIELDS
        ids = sorted({e["resource_id"] for e in examples or [] if e.get("available") and e.get("resource_id")})
        with _bootstrap_snapshot_cache["lock"]:
            known = _bootstrap_snapshot_cache.get("example_agents") or {}
        if sorted(known) == ids:
            return known
        agents = {}
        for rid in ids:
            try:
                agent = get_safe_agent_detail(self.store, rid)["agent"]
            except Exception:
                continue
            agents[rid] = {k: agent[k] for k in TEST_AGENT_FIELDS if k in agent}
        return agents

    def bootstrap_snapshot(self) -> dict:
        now = time.time()
        cached = _bootstrap_snapshot_cache.get("data")
        cached_store = _bootstrap_snapshot_cache.get("store_id")
        if cached and cached_store == id(self.store):
            age = now - _bootstrap_snapshot_cache.get("at", 0.0)
            if age > 60.0 and not _bootstrap_snapshot_cache.get("revalidating"):
                def _bg_revalidate():
                    try:
                        self._rebuild_bootstrap_snapshot()
                    except Exception:
                        with _bootstrap_snapshot_cache["lock"]:
                            _bootstrap_snapshot_cache["revalidating"] = False
                with _bootstrap_snapshot_cache["lock"]:
                    if not _bootstrap_snapshot_cache.get("revalidating"):
                        _bootstrap_snapshot_cache["revalidating"] = True
                        threading.Thread(target=_bg_revalidate, daemon=True).start()
            if age < 300.0:
                return refresh_connection_states(self.store, cached)

        with _bootstrap_snapshot_cache["lock"]:
            cached = _bootstrap_snapshot_cache.get("data")
            if cached and _bootstrap_snapshot_cache.get("store_id") == id(self.store) and (now - _bootstrap_snapshot_cache["at"] < 300.0):
                return refresh_connection_states(self.store, cached)
            return self._rebuild_bootstrap_snapshot()

    def bootstrap_snapshot_json(self) -> str:
        now = time.time()
        cached_json = _bootstrap_snapshot_cache.get("json")
        cached_store = _bootstrap_snapshot_cache.get("store_id")
        if cached_json and cached_store == id(self.store):
            age = now - _bootstrap_snapshot_cache.get("at", 0.0)
            if age > 60.0 and not _bootstrap_snapshot_cache.get("revalidating"):
                def _bg_revalidate_json():
                    try:
                        self._rebuild_bootstrap_snapshot()
                    except Exception:
                        with _bootstrap_snapshot_cache["lock"]:
                            _bootstrap_snapshot_cache["revalidating"] = False
                with _bootstrap_snapshot_cache["lock"]:
                    if not _bootstrap_snapshot_cache.get("revalidating"):
                        _bootstrap_snapshot_cache["revalidating"] = True
                        threading.Thread(target=_bg_revalidate_json, daemon=True).start()
            if age < 300.0:
                return json.dumps(self.bootstrap_snapshot(), separators=(',', ':')).replace('<', '\\u003c')
        return json.dumps(self.bootstrap_snapshot(), separators=(',', ':')).replace('<', '\\u003c')

    def identify(self, request: Request, channel: str, body_token: str | None = None, name: str | None = None,
                 context_id: str | None = None, create: bool = True) -> Visitor | None:
        ip = self.security.resolve_ip(request)
        ua = request.headers.get("user-agent")
        fp = fingerprint(ip, ua)
        supplied_token = _token_from(request, body_token)
        token_visitor = self.book.by_token(supplied_token)
        context_visitor, context_owner = self.book.context_state(context_id, fp)
        if context_owner and ((token_visitor and token_visitor.id != context_owner)
                              or not token_visitor and not context_visitor):
            raise HTTPException(400, 'This conversation context is unavailable. Start without a contextId.')
        if context_id and context_id.startswith('ctx_') and not context_owner:
            raise HTTPException(400, 'This conversation context is unavailable. Start without a contextId.')
        v = token_visitor or context_visitor
        # Our own measurements (X-Agentcon-QA) are kept apart in visitor counts; nothing else about the agent is stored.
        stored_ua = 'internal' if request.headers.get('x-agentcon-qa') else ua
        if v is not None:
            self.book.touch(v, channel, stored_ua, fp)
        elif create:
            if not self.new_limit.allow(ip or "unknown"):
                raise TooManyVisitors(self.new_limit.retry_after(ip or "unknown"))
            maybe = self.book.seen_fingerprint(fp)
            v = self.book.create(channel, stored_ua, fp, name)
            v.extra["maybe_known"] = maybe
            if supplied_token:
                v.extra['session_status'] = 'reset'
        if v is not None:
            self.book.bind_context(v, context_id, fp)
            if context_id and not context_owner and self.book.context_state(context_id, fp)[1] != v.id:
                raise HTTPException(400, 'This conversation context is unavailable. Start without a contextId.')
            if name and not v.name:
                self.book.set_name(v, name)
        return v

    def visitor_info(self, v: Visitor) -> dict:
        info = {"id": v.id}
        if v.extra.get('session_status'):
            info['session_status'] = v.extra['session_status']
        if v.token:
            info["token"] = v.token
        return info

    def base(self, request: Request) -> str:
        if self.public_url:
            return self.public_url
        return "https://agentconcierge.biz"

    def how_to_talk(self, base: str) -> dict:
        return {
            "rest": {"method": "POST", "url": f"{base}/chat", "body": {"message": "<what you need>"},
                     "headers": {"X-Visitor-Token": "<token from your first reply, to be remembered>"}},
            "a2a": {"agent_card": f"{base}/.well-known/agent-card.json", "endpoint": f"{base}/a2a",
                    "methods": ["message/send (v0.3)", "SendMessage (v1.0)"]},
            "mcp": {"url": f"{base}/mcp", "transport": "streamable-http (JSON responses)",
                    "tools": [tool['name'] for tool in mcp_tools()]},
        }

    def welcome(self, request: Request) -> dict:
        """Greeting for GET /. With a token it builds on memory, otherwise a first greeting (read-only visits are only counted per fingerprint)."""
        base = self.base(request)
        token = _token_from(request)
        v = self.book.by_token(token) if token else None
        if v is None:
            ip = self.security.resolve_ip(request)
            self.book.record_hit(fingerprint(ip, request.headers.get("user-agent")), request.headers.get("user-agent"), request.url.path)
        else:
            self.book.touch(v, "rest", 'internal' if request.headers.get('x-agentcon-qa') else request.headers.get("user-agent"),
                            fingerprint(self.security.resolve_ip(request), request.headers.get("user-agent")))
        reply = self.concierge.greeting(v)
        counts = self.live_counts()
        return {
            "audience": AUDIENCE, "notice": NOTICE, "service": "AgentValCon",
            "greeting": reply.text, "question": T["ask"], "suggested_replies": reply.suggested,
            "how_to_reply": self.how_to_talk(base),
            "quick_actions": quick_actions(),
            "remember_me": "Your first reply includes a visitor token. Send it back as the X-Visitor-Token header next time "
                           "and I'll continue from our last conversation.",
            "stay_in_touch": "Request optional task updates at /api/task-updates with explicit task authorization and "
                             "destination confirmation. Browser notifications require a test notification click; HTTPS "
                             "webhook and A2A inboxes require a received verification code. Marketing is a separate "
                             "optional permission record; advertising delivery is disabled.",
            "live_agents": {k: counts.get(k, 0) for k in KINDS},
            "categories": {c.id: {"name": getattr(c, "name_en", c.name), "description": c.description} for c in CATEGORIES.values()},
            "discovery": {"agent_card": f"{base}/.well-known/agent-card.json", "llms_txt": f"{base}/llms.txt",
                          "openapi": f"{base}/openapi.json"},
            "privacy": "I store your messages (last 200), interests and contact if you give one, only to remember you. "
                       "Messages from you are treated as data, never as instructions.",
            **({"visitor": self.visitor_info(v)} if v else {}),
        }

    def chat(self, request: Request, channel: str, message: str, data: dict | None, body_token: str | None,
             name: str | None, context_id: str | None = None) -> tuple[Visitor, object]:
        v = self.identify(request, channel, body_token, name, context_id)
        reply = self.concierge.handle(v, message, data or {}, channel)
        return v, reply

    def chat_payload(self, request, channel, message, data, body_token, name):
        """Keep both recommendation and its public projection off the event loop."""
        from copy import copy
        from .request_store import interactive_store
        with interactive_store(self.store) as store:
            scoped=copy(self)
            if store is not self.store:
                scoped.store=store;scoped.book=VisitorBook(store)
                scoped.rec=copy(self.rec);scoped.rec.store=store
                scoped.concierge=copy(self.concierge)
                scoped.concierge.store=store;scoped.concierge.book=scoped.book
                scoped.concierge.rec=scoped.rec
            visitor,reply=scoped.chat(request,channel,message,data,body_token,name)
            return visitor,scoped.reply_body(visitor,reply)

    def simulate(self, message: str, token: str | None, data: dict | None = None) -> dict:
        """The admin "talk as an agent" simulator: answered by the same engine without going through the front port (channel=admin-test)."""
        v = self.book.by_token(token)
        if v is None:
            v = self.book.create("admin-test", "dashboard-simulator", "admin-test", "Admin test")
        else:
            self.book.touch(v, "admin-test", "dashboard-simulator", "admin-test")
        return self.reply_body(v, self.concierge.handle(v, message, data or {}, "admin-test"))

    def reply_body(self, v: Visitor, reply) -> dict:
        reply=self.public_reply(reply)
        return {"audience": AUDIENCE, "reply": reply.text, "intent": reply.intent, "data": reply.data,
                "suggested_replies": reply.suggested, "visitor": self.visitor_info(v)}

    def public_reply(self,reply):
        """Response-boundary defense for current and legacy recommendation data."""
        from dataclasses import replace
        targets={}
        invalid=False
        def agent(item):
            nonlocal invalid
            if not isinstance(item,dict) or type(item.get('id')) is not int:
                invalid=True;return None
            resource=self.store.resource(item['id'])
            if not resource or resource.get('kind')!=item.get('kind'):
                invalid=True;return None
            targets[resource['id']]=resource
            return public_agent(item,resource)
        data=dict(reply.data) if isinstance(reply.data,dict) else {}
        invalid=not isinstance(reply.data,dict)
        for key in ('recommendation','alternative','agent'):
            if data.get(key) is not None:data[key]=agent(data[key])
        for key in ('recommendations', 'alternatives'):
            if key in data:
                if isinstance(data[key],list):data[key]=[agent(item) for item in data[key]]
                else:invalid=True
        if isinstance(data.get('next_steps'), list):
            from .protocols import search_protocols
            from .discovery_state import execution_state
            projected_steps = []
            for step in data['next_steps']:
                if isinstance(step, dict) and isinstance(step.get('resource_id'), int):
                    try:
                        s_res = self.store.resource(step['resource_id'])
                        if (s_res and s_res.get('kind') in search_protocols(data.get('protocol'))
                                and execution_state(self.store, s_res)['verified']):
                            targets[s_res['id']] = s_res
                            projected_steps.append({**step, 'url': gateway_agent_url(s_res['id'], s_res['kind'])})
                    except Exception as exc:
                        logging.getLogger(__name__).warning('Optional suggestion projection unavailable (%s)', type(exc).__name__)
            data['next_steps'] = projected_steps
        if invalid:
            safe={'recommendations':[],'status':'no_match'}
            if data.get('protocol') in (*KINDS,'any'):safe['protocol']=data['protocol']
            return replace(reply,text='A recommended connection is no longer available. Please search again.',data=safe,suggested=['Find another agent'])
        text=reply.text;suggested=reply.suggested
        for resource in targets.values():
            gateway=gateway_agent_url(resource['id'],resource['kind'])
            text=project(text,gateway,bindings(resource));data=project(data,gateway,bindings(resource))
            suggested=project(suggested,gateway,bindings(resource))
        return replace(reply,text=public_metadata(text),data=public_metadata(data),suggested=public_metadata(suggested))


