class _ExploreResultCache:
    """Repeated public searches within a short window reuse one computed result.

    Results hold only public listing projections; execution still checks current
    authority and evidence independently, so a reuse cannot grant access, and
    revalidated_page() re-reads every listing's current state before a page is shown.
    A first search took 2 to 8 seconds, so a typed search is kept for 15 minutes, not 30 seconds.
    """
    def __init__(self, ttl=900.0, maximum=512):
        self.ttl, self.maximum = ttl, maximum
        self.values, self.lock = OrderedDict(), threading.Lock()
        self.inflight = {}
        # Search (key without its window) -> key of a result that examined every candidate.
        self.finished = OrderedDict()

    def complete(self, key):
        """A result that examined every candidate answers any window of the same search,
        so Load More reuses it instead of repeating the search."""
        with self.lock:
            wider = self.finished.get(key[:-1])
            found = self.values.get(wider) if wider is not None else None
            if found is None or time.monotonic() > found[0]:
                return None
            self.values.move_to_end(wider)
            return found[1]

    def get(self, key):
        with self.lock:
            found = self.values.get(key)
            if found is None or time.monotonic() > found[0]:
                self.values.pop(key, None)
                return None
            self.values.move_to_end(key)
            return found[1]

    def load(self, key, compute, wait_seconds=15):
        """Collapse concurrent misses; every reused page still passes live-state checks."""
        with self.lock:
            found=self.values.get(key)
            if found is not None and found[0]>=time.monotonic():
                self.values.move_to_end(key)
                return found[1],True
            flight=self.inflight.get(key)
            owner=flight is None
            if owner:
                if len(self.inflight)>=self.maximum:
                    raise HTTPException(503,'Search is busy. Please try again shortly.',headers={'Retry-After':'1'})
                flight={'event':threading.Event()}
                self.inflight[key]=flight
        if not owner:
            if not flight['event'].wait(wait_seconds) or 'value' not in flight:
                raise HTTPException(503,'Search is busy. Please try again shortly.',headers={'Retry-After':'1'})
            return flight['value'],True
        try:
            value=compute()
            self.put(key,value)
            flight['value']=value
            return value,False
        finally:
            with self.lock:
                self.inflight.pop(key,None)
                flight['event'].set()

    def put(self, key, value, ttl=None):
        with self.lock:
            self.values[key] = (time.monotonic() + (self.ttl if ttl is None else ttl), value)
            self.values.move_to_end(key)
            if isinstance(value, dict) and value.get('complete') is True:
                self.finished.pop(key[:-1], None)
                self.finished[key[:-1]] = key
                while len(self.finished) > self.maximum:
                    self.finished.popitem(last=False)
            while len(self.values) > self.maximum:
                self.values.popitem(last=False)

    def clear(self):
        with self.lock:
            self.values.clear()
            self.finished.clear()


