class _QueryPopularity:
    """In-process counts of public Explore searches, used only to choose what to keep warm.

    Nothing is stored or shown; only plain task phrases qualify, so an address, a
    number or a long sentence a visitor typed is never recomputed in the background."""
    PLAIN = re.compile(r'[a-z][a-z0-9 .+#-]{1,59}')
    def __init__(self, window=3600.0, maximum=2048):
        self.window, self.maximum = window, maximum
        self.seen, self.lock = OrderedDict(), threading.Lock()

    def record(self, query):
        query = ' '.join(str(query).casefold().split())
        if not self.PLAIN.fullmatch(query) or re.search(r'\d{5,}', query):
            return
        now = time.monotonic()
        with self.lock:
            hits = [at for at in self.seen.pop(query, []) if now - at <= self.window][-20:]
            self.seen[query] = hits + [now]
            while len(self.seen) > self.maximum:
                self.seen.popitem(last=False)

    def top(self, count=16, minimum=3):
        now = time.monotonic()
        with self.lock:
            ranked = sorted(((sum(now - at <= self.window for at in hits), query) for query, hits in self.seen.items()), reverse=True)
        return [query for hits, query in ranked if hits >= minimum][:count]


_explore_popularity = _QueryPopularity()


