class _PageSnapshots:
    """Served result order per search, so a later page never repeats or skips what was shown.

    Pages are computed with growing windows (offset+limit+1), and a larger window can rank
    new listings ahead of ones already served. The first page records its order; later pages
    keep that prefix and continue with listings not yet shown."""

    def __init__(self, ttl=600.0, maximum=512, clock=time.monotonic):
        self.values, self.lock, self.ttl, self.maximum, self.clock = collections.OrderedDict(), threading.Lock(), ttl, maximum, clock

    def get(self, key):
        with self.lock:
            found = self.values.get(key)
            return list(found[1]) if found and found[0] > self.clock() else None

    def put(self, key, ids):
        with self.lock:
            self.values.pop(key, None)
            self.values[key] = (self.clock() + self.ttl, tuple(ids))
            while len(self.values) > self.maximum:
                self.values.popitem(last=False)


_page_snapshots = _PageSnapshots()


def _continue_snapshot(key, result, offset, limit):
    items = [item for item in result.get('items', []) if isinstance(item, dict)]
    if offset == 0:
        _page_snapshots.put(key, [item.get('id') for item in items[:limit]])
        return result
    served = _page_snapshots.get(key)
    if not served or len(served) < offset:
        return result
    shown = set(served[:offset])
    rest = [item for item in items if item.get('id') not in shown]
    _page_snapshots.put(key, served[:offset] + [item.get('id') for item in rest[:limit]])
    # Placeholders hold the served positions; page() slices them away.
    return {**result, 'items': [{'id': rid} for rid in served[:offset]] + rest}


class _NextPagePrefetch:
    """After a first page that did not examine every candidate, compute the Load More window.

    One background worker and a short queue: at most one extra search runs at a time, and
    a full queue drops the request, so a visitor's own search never waits for this work.
    Load More finds the result cached, or joins the in-flight computation."""

    def __init__(self, maximum=8):
        import queue
        self.queue, self.lock, self.thread = queue.Queue(maximum), threading.Lock(), None

    def submit(self, key, compute):
        import queue
        try:
            self.queue.put_nowait((key, compute))
        except queue.Full:
            return False
        with self.lock:
            if self.thread is None or not self.thread.is_alive():
                self.thread = threading.Thread(target=self._run, name='explore-next-page', daemon=True)
                self.thread.start()
        return True

    def _run(self):
        import queue
        while True:
            try:
                key, compute = self.queue.get(timeout=30)
            except queue.Empty:
                return
            try:
                if _explore_result_cache.get(key) is None and _explore_result_cache.complete(key) is None:
                    _explore_result_cache.load(key, compute)
            except Exception:
                logging.getLogger(__name__).warning('Explore next-page prefetch skipped', exc_info=False)


_next_page_prefetch = _NextPagePrefetch()


SHARED_EXPLORE_TTL = 600
SHARED_EXPLORE_MAX_BYTES = 2 * 1024 * 1024


def _shared_explore_keys(store, key):
    """Redis keys shared by both frontend slots: the search without the process-local store id,
    and the same search without its window for a result that examined every candidate."""
    import os
    root = os.environ.get('AGENTCON_PROJECT_ROOT')
    if getattr(store, 'backend', None) == 'postgresql' and root:
        # _redis_cache_prefix() gives a PostgreSQL store a per-process test prefix; a deployed
        # service (project root set by service_host) shares one prefix across slots and restarts.
        prefix = 'a2a:shared:' + hashlib.sha256(root.encode()).hexdigest()[:12] + ':cache:explore-result:v1:'
    else:
        prefix = _redis_cache_prefix(store) + 'cache:explore-result:v1:'
    digest = lambda value: hashlib.sha256(json.dumps(value, default=str).encode()).hexdigest()[:32]
    return prefix + digest(list(key[1:])), prefix + 'complete:' + digest(list(key[1:-1]))


def _shared_explore(store, key, compute, hit):
    """Wrap COMPUTE with a Redis lookup shared across slots and restarts.

    A shared result is public listing projections only, and the caller re-reads every listing
    (revalidated_page) before showing it. Redis being unavailable, or a value that cannot be
    encoded within the size limit, only skips the shared layer."""
    def load():
        hub = RedisHub.get_instance()
        exact, finished = _shared_explore_keys(store, key)
        if hub.is_available():
            from .retrieval_metrics import stage
            with stage('shared_cache'):
                for name in (exact, finished):
                    found = hub.get_json(name)
                    if isinstance(found, dict) and isinstance(found.get('items'), list):
                        hit.append(name)
                        return found
        value = compute()
        if hub.is_available() and isinstance(value, dict):
            try:
                encoded = json.dumps(value, ensure_ascii=False)
            except (TypeError, ValueError):
                return value
            if len(encoded) <= SHARED_EXPLORE_MAX_BYTES:
                hub.set_json(exact, value, ttl_seconds=SHARED_EXPLORE_TTL)
                if value.get('complete') is True:
                    hub.set_json(finished, value, ttl_seconds=SHARED_EXPLORE_TTL)
        return value
    return load


def warm_explore(front, queries=None, *, stop=None, pause=0.0):
    """Recompute the default Explore page for public chip searches, one at a time.

    The same public projection a visitor would receive is stored for ten minutes;
    a visitor's own search never waits for this work, and a failure is skipped."""
    from .discovery import discovery_store
    from .hybrid_explore import explore
    warmed = 0
    if getattr(front.store, 'backend', None) != 'postgresql':
        return warmed
    queries = explore_warm_queries() if queries is None else queries
    for query in queries:
        if stop is not None and stop.is_set():
            break
        try:
            with discovery_store(front.store) as scoped:
                result = explore(scoped, front.rag_engine, query, None, None, False, False, 46)
            _explore_result_cache.put(explore_cache_key(front, query, None, None, False, False, 46), result, EXPLORE_WARM_TTL)
            warmed += 1
        except Exception:
            logging.getLogger(__name__).warning('Explore keep-warm query skipped', exc_info=False)
        if pause and stop is not None:
            stop.wait(pause)
    return warmed
_bootstrap_snapshot_cache = {
    "at": 0.0,
    "data": None,
    "json": None,
    "store_id": None,
    "lock": threading.RLock(),
    "revalidating": False,
}


def _redis_cache_prefix(store: Store | None = None) -> str:
    if store is None:
        return "a2a:"
    db_path = getattr(store, "_path", getattr(store, "path", ""))
    if not db_path or ":memory:" in str(db_path) or "pytest" in str(db_path) or "/tmp" in str(db_path) or "/var/folders" in str(db_path):
        return f"a2a:test:{id(store)}:"
    return "a2a:"
