# Catalog statistics and featured listings change slowly, and every served copy still rechecks each
# listing's execution badge (refresh_connection_states). A first computation takes 3-3.5 s (11-11
# /api/insights 4.15 s on the public site), so it runs at most once per half hour per process.
INSIGHTS_SECONDS = 1800.0


def get_front_insights(store: Store, fresh: bool = False) -> dict:
    """Protocol statistics and featured agents for Learn section.

    Public requests read the jobs snapshot (insights_snapshot.served); this computation runs in the jobs service
    with FRESH set, and in a request only before the first snapshot exists (11-13 01:49: a 500 at the 5 s
    statement timeout under load)."""
    now = time.time()
    store_id = id(store)
    cached = _front_insights_cache.get("data")
    if not fresh and cached and (_front_insights_cache.get("store_id") == store_id) and (now - _front_insights_cache["at"] < INSIGHTS_SECONDS):
        return refresh_connection_states(store, cached)

    redis_hub = RedisHub.get_instance()
    pfx = _redis_cache_prefix(store)
    if not fresh and redis_hub.is_available():
        cached_redis = redis_hub.get_json(f"{pfx}cache:insights:v2")
        if cached_redis is not None:
            _front_insights_cache["at"] = now
            _front_insights_cache["data"] = cached_redis
            _front_insights_cache["store_id"] = store_id
            return refresh_connection_states(store, cached_redis)

    featured_sql = {
        "x402": [
            ("newest", "Recently Discovered APIs", "1=1", "r.first_seen DESC"),
            ("verified", "Execution-Checked APIs", VERIFIED_EXECUTION_COND, "r.eval_score DESC"),
            ("most_paid", "Most Paid APIs (Last 30 Days)", "r.payers_30d IS NOT NULL", "r.payers_30d DESC"),
            ("cheapest", "Lowest Cost Micro-Payment APIs", "r.price_usdc > 0 AND r.health_status='healthy'", "r.price_usdc ASC, COALESCE(r.payers_30d,0) DESC"),
        ],
        "mcp": [
            ("newest", "Recently Registered Tool Servers", "1=1", "r.first_seen DESC"),
            ("verified", "Execution-Checked Tool Servers", VERIFIED_EXECUTION_COND, "r.eval_score DESC"),
            ("open", "Zero-Authentication Open Servers", "COALESCE(r.auth_observed, r.auth_declared, 1)=0 AND r.eval_grade='A'", "r.cap_tool_count DESC"),
        ],
        "a2a": [
            ("newest", "Recently Discovered Agents", "1=1", "r.first_seen DESC"),
            ("verified", "Execution-Checked Agents", VERIFIED_EXECUTION_COND, "COALESCE(r.eval_score,0) DESC"),
            ("top", "Highest Quality Rated Agents", "r.eval_score IS NOT NULL", "r.eval_score DESC"),
        ],
    }

    def q(sql, p=()):
        return [dict(r) for r in store.query(sql, p)]

    base = "FROM resources r WHERE r.active=1 AND r.health_status != 'retired'"
    stats = {
        r["kind"]: r
        for r in q(
            f"""SELECT r.kind, COUNT(*) AS total,
                SUM(r.health_status IN ('healthy','reachable')) AS live,
                SUM(r.first_seen > ?) AS new_24h,
                SUM(r.first_seen > ?) AS new_7d,
                SUM(r.trial_ok = 1) AS verified,
                SUM({VERIFIED_EXECUTION_COND}) AS execution_verified,
                SUM(COALESCE(r.auth_observed, r.auth_declared) = 0) AS no_auth,
                SUM(r.auth_autonomy = 'agent_autonomous') AS agent_autonomous,
                SUM(r.eval_grade = 'A') AS grade_a,
                SUM(r.cap_tool_count) AS tools,
                SUM(COALESCE(r.payers_30d, 0)) AS payers_30d,
                SUM(COALESCE(r.calls_30d, 0)) AS calls_30d,
                MIN(CASE WHEN r.price_usdc > 0 THEN r.price_usdc END) AS min_price,
                SUM(r.price_usdc > 0 AND r.price_usdc <= 10000) AS under_1cent,
                SUM(r.price_usdc > 0) AS priced
              {base} GROUP BY r.kind""", (now - 86400, now - 7 * 86400)
        )
    }

    prices: dict = {}
    median_rows = getattr(store, "insight_price_medians", None)
    price_rows = median_rows() if callable(median_rows) else q(
        f"SELECT r.kind, r.price_usdc {base} AND r.price_usdc > 0 ORDER BY r.price_usdc")
    for r in price_rows:
        prices.setdefault(r["kind"], []).append(r["price_usdc"])

    cats: dict = {}
    for r in q(f"SELECT r.kind, r.category, COUNT(*) AS n {base} GROUP BY r.kind, r.category ORDER BY n DESC"):
        cats.setdefault(r["kind"], []).append({"category": r["category"], "n": r["n"]})

    sources: dict = {}
    for r in q("SELECT kind, source, COUNT(*) AS n FROM resources WHERE active=1 GROUP BY kind, source ORDER BY n DESC"):
        sources.setdefault(r["kind"], []).append({"source": r["source"], "n": r["n"]})

    kinds_out = {}
    for kind in KINDS:
        s = stats.get(kind) or {"total": 0, "live": 0}
        kp = prices.get(kind, [])
        s["median_price"] = kp[len(kp) // 2] if kp else None
        feat_list = []
        for key, title, cond, order in featured_sql.get(kind, []):
            rows = q(
                f"SELECT {CARD_COLS} FROM resources r WHERE {LIVE_COND} AND r.kind=? AND {cond} ORDER BY {order} LIMIT 30",
                (kind,)
            )
            # A public read creates no connection rows (11-11: one write transaction per featured card).
            cards = [_card_data(r,store,create_connections=False) for r in _diverse_hosts(rows, 6)]
            if key == 'verified':
                cards = [card for card in cards if card.get('connection_readiness',{}).get('verified_callable')]
            feat_list.append({"key": key, "title": title, "items": cards})
        kinds_out[kind] = {
            "stats": s,
            "top_categories": cats.get(kind, [])[:6],
            "sources": sources.get(kind, []),
            "featured": feat_list,
        }

    out = {
        "now": now,
        "categories": {c.id: getattr(c, "name_en", c.name) for c in CATEGORIES.values()},
        "kinds": kinds_out,
    }
    if redis_hub.is_available():
        redis_hub.set_json(f"{pfx}cache:insights:v2", out, ttl_seconds=int(INSIGHTS_SECONDS))
    _front_insights_cache["at"] = now
    _front_insights_cache["data"] = out
    _front_insights_cache["store_id"] = store_id
    return out


def get_front_workflow_templates(store: Store, category: str | None = None, q: str | None = None) -> list[dict]:
    """Search reviewed public workflows without dispatching their nodes."""
    from .workflow_discovery import published_templates
    return published_templates(store, category, q)


def _report_candidate_sql(terms, where):
    """Count and candidate statements of a report-filtered search; the text is shared with the snapshot."""
    if terms:
        match = " OR ".join('"' + term.replace('"','') + '"' for term in terms)
        count_sql = f"""SELECT COUNT(*) AS c FROM resources_fts f JOIN resources r ON r.id=f.rowid
                WHERE resources_fts MATCH ? AND {where}"""
        candidate_sql = f"""SELECT {CARD_COLS} FROM resources_fts f JOIN resources r ON r.id=f.rowid
                WHERE resources_fts MATCH ? AND {where}
                ORDER BY bm25(resources_fts) - COALESCE(r.eval_score, 50) / 100.0 - (r.trial_ok IS 1) * 0.5, r.id DESC LIMIT ? OFFSET ?"""
        return count_sql, candidate_sql, (match,)
    return (f"SELECT COUNT(*) AS c FROM resources r WHERE {where}",
            f"""SELECT {CARD_COLS} FROM resources r WHERE {where}
                ORDER BY COALESCE(r.first_seen, 0) DESC, r.id DESC LIMIT ? OFFSET ?""", ())


def _report_candidates(store, count_sql, candidate_sql, prefix, values):
    """Read up to MAX_REPORT_CANDIDATES ranked candidates; returns them with the coarse total."""
    count_rows = store.query(count_sql, (*prefix,*values))
    coarse_total = int(count_rows[0]['c']) if count_rows else 0
    candidates = []
    while len(candidates) < min(coarse_total,MAX_REPORT_CANDIDATES):
        # Each page read ranks every match again, so read the window in as few pages as rows allow.
        batch_size = min(2000,MAX_REPORT_CANDIDATES-len(candidates))
        rows = store.query(candidate_sql,(*prefix,*values,batch_size,len(candidates)))
        if not rows:break
        candidates.extend(dict(row) for row in rows)
        if len(rows) < batch_size:break
    return candidates, coarse_total


def _report_listing(store, row, current, report_rows):
    """ROW with its checked report metadata, or None. The query-dependent adult rule is the caller's."""
    resource = (current or {}).get(row['id']) or store.resource(row['id'])
    if (not resource or policy_excluded(resource) or resource.get('health_status') == 'quarantined'
            or resource.get('kind') != row['kind']):
        return None, resource
    metadata = _card_report_metadata(store,resource,None if report_rows is None else report_rows.get(row['id'],[]))
    if not metadata['report_count']:
        return None, resource
    row.update(metadata)
    row['active'] = bool(resource.get('active'))
    row['health_status'] = resource.get('health_status')
    row['catalog_status'] = ('live' if row['active'] and resource.get('health_status')
                             in ('healthy','reachable') else 'historical')
    return row, resource


def _report_result(store, q_clean, terms, valid, cards, target_kinds, verified, limit, unseen=0):
    """The public report-filtered page from checked rows (CARDS: precomputed cards by id)."""
    by_kind = {protocol:_diverse_hosts([row for row in valid if row['kind']==protocol],limit,per_host=999)
               for protocol in target_kinds}
    selected = []
    for index in range(max((len(group) for group in by_kind.values()),default=0)):
        for protocol in target_kinds:
            if index < len(by_kind[protocol]):
                selected.append(by_kind[protocol][index])
                if len(selected) >= limit:break
        if len(selected) >= limit:break
    result = {'query':q_clean,'terms':terms,'has_report':True,'total':len(valid)+unseen,
              'total_is_estimate':bool(unseen),'candidate_window_limited':bool(unseen),
              'total_unit':'agents','report_scope':'live' if verified else 'history',
              'matched_report_count':None if unseen else sum(row['report_count'] for row in valid),
              'historical_agent_count':None if unseen else sum(row['catalog_status'] == 'historical' for row in valid),
              'items':[cards.get(row['id']) or _card_data(row,store,create_connections=False) for row in selected]}
    if verified:result['verified'] = True
    return result


def _report_filtered_explore(store, q_clean, terms, kind, conds, params, verified, limit):
    """Validate report identity before the bounded result page is selected."""
    from .content_policy import hidden_from_public_list
    target_kinds = [kind] if kind else ["a2a","mcp","x402"]
    clauses = conds + (["r.kind=?"] if kind else [])
    values = [*params,*([kind] if kind else [])]
    count_sql, candidate_sql, prefix = _report_candidate_sql(terms, " AND ".join(clauses))
    candidates, coarse_total = _report_candidates(store, count_sql, candidate_sql, prefix, values)
    valid = []
    verified_cards = {}
    current, report_rows = _report_prefetch(store, [row['id'] for row in candidates if row['kind'] in target_kinds])
    for row in candidates:
        if row['kind'] not in target_kinds:
            continue
        row, resource = _report_listing(store, row, current, report_rows)
        if row is None or hidden_from_public_list(resource, q_clean):
            continue
        if verified:
            # A public search only reads; it never registers connection versions.
            card = _card_data(row,store,create_connections=False)
            if not card.get('connection_readiness',{}).get('verified_callable'):
                continue
            verified_cards[row['id']] = card
        valid.append(row)
    return _report_result(store, q_clean, terms, valid, verified_cards, target_kinds, verified, limit,
                          max(0,coarse_total-len(candidates)))


def _exact_name_first(query: str, items: list[dict], pool: list[dict], limit: int) -> list[dict]:
    """A search for an agent's exact name shows that agent first.

    Only candidates the text search already returned are reordered; no new
    query or relevance rule is introduced."""
    needle = " ".join(str(query or "").casefold().split())
    if len(needle) < 3:
        return items
    def rank(row):
        name = " ".join(str(row.get("name") or "").casefold().split())
        return 0 if name == needle else 1 if needle in name else 2
    seen, named = set(), []
    for row in sorted(pool, key=rank):
        if rank(row) == 2:
            break
        if row.get("id") not in seen:
            seen.add(row.get("id")); named.append(row)
    if not named:
        return items
    return (named + [row for row in items if row.get("id") not in seen])[:limit]


def get_front_explore(store: Store, q: str, kind: str | None, category: str | None,
                      verified: bool, no_auth: bool, limit: int = 45, has_report: bool = False) -> dict:
    """Explore agents with in-memory caching to prevent server slowdown."""
    from .protocols import requested_protocol, search_protocols, merge_discovery_results
    selected = requested_protocol(q, {'kind': kind})
    if selected is None:
        return merge_discovery_results([get_front_explore(store, q, protocol, category, verified, no_auth, limit, has_report)
                                        for protocol in search_protocols()], limit)
    kind = selected
    now = time.time()
    cache_key = f"{id(store)}|{q}|{kind}|{category}|{int(verified)}|{int(no_auth)}|{int(has_report)}|{limit}"
    cacheable = not (has_report or verified)
    if cacheable and cache_key in _front_explore_cache:
        cached_time, cached_val = _front_explore_cache[cache_key]
        if now - cached_time < 120.0:
            with store._lock:
                return refresh_connection_states(store, cached_val)

    redis_hub = RedisHub.get_instance()
    pfx = _redis_cache_prefix(store)
    redis_explore_key = f"{pfx}cache:explore:{hashlib.sha256(cache_key.encode('utf-8')).hexdigest()[:24]}"
    if cacheable and redis_hub.is_available():
        cached_redis = redis_hub.get_json(redis_explore_key)
        if cached_redis is not None:
            with _front_explore_cache_lock:
                _front_explore_cache[cache_key] = (now, cached_redis)
            with store._lock:
                return refresh_connection_states(store, cached_redis)

    q_clean = (q or "").replace("\x00", "").strip()[:500]
    # Historical report search is independent of current reachability. Execution
    # filtering retains the live catalog boundary and current evidence checks.
    conds = [REPORT_HISTORY_COND if has_report and not verified else LIVE_COND]
    params: list = []
    if category:
        conds.append("r.category=?")
        params.append(category)
    if verified:
        conds.append(VERIFIED_EXECUTION_COND)
    if no_auth:
        conds.append("(COALESCE(r.auth_observed, r.auth_declared, 0)=0 OR r.kind='x402')")
    if has_report:
        conds.extend(REPORT_CONDS)

    target_kinds = [kind] if kind else ["a2a", "mcp", "x402"]
    from .selection import search_terms
    from .discovery import normalize_task
    terms = search_terms(normalize_task(q_clean))[:12] or query_terms(q_clean, limit=12)
    per_host = 999 if has_report else 2
    if has_report:
        from .report_snapshot import current as report_snapshot
        snapshot = report_snapshot(store)
        if snapshot is not None:
            # Explore may answer from data a few minutes old (policy 2026-11-01); the shown page
            # is still re-read, so quarantine and withdrawn report trust apply at once.
            return revalidated_page(store, snapshot.search(store,q_clean,terms,kind,category,verified,no_auth,limit))
        # One read snapshot for every candidate check: a transaction per read cost about 3 ms,
        # and some 7,800 listings with reports made the first page take 16 to 48 seconds.
        snapshot = store.tx(readonly=True) if getattr(store, "backend", None) == "postgresql" else nullcontext()
        with store._lock, snapshot:
            return _report_filtered_explore(store,q_clean,terms,kind,conds,params,verified,limit)

    def run_q(sql, p):
        rows = [dict(r) for r in store.query(sql, p)]
        if terms:
            from .explore_search import task_advertised
            rows = [row for row in rows if task_advertised(q_clean, store.resource(row['id']))]
        return rows

    if len(target_kinds) == 1:
        k_conds = conds + ["r.kind=?"]
        k_params = params + [target_kinds[0]]
        where = " AND ".join(k_conds)
        if terms:
            match = " OR ".join('"' + t.replace('"', "") + '"' for t in terms)
            rows = run_q(
                f"""SELECT {CARD_COLS} FROM resources_fts f JOIN resources r ON r.id=f.rowid
                    WHERE resources_fts MATCH ? AND {where}
                    ORDER BY bm25(resources_fts) - COALESCE(r.eval_score, 50) / 100.0 - (r.trial_ok IS 1) * 0.5 LIMIT ?""",
                (match, *k_params, limit * 4)
            )
        else:
            rows = run_q(
                f"""SELECT {CARD_COLS} FROM resources r WHERE {where}
                    ORDER BY COALESCE(r.first_seen, 0) DESC, r.id DESC LIMIT ?""",
                (*k_params, limit * 4)
            )
        items = _exact_name_first(q_clean, _diverse_hosts(rows, limit, per_host=per_host), rows, limit)
        # Keep FTS as the outer loop: a resource-first count repeats the text
        # lookup for every live catalog row while holding the shared store lock.
        cnt_rows = (store.query(f"""SELECT COUNT(*) AS c FROM resources_fts f CROSS JOIN resources r
                    WHERE r.id=f.rowid AND resources_fts MATCH ? AND {where}""",(match,*k_params)) if terms else
                    store.query(f"SELECT COUNT(*) AS c FROM resources r WHERE {where}", k_params))
        total = cnt_rows[0]["c"] if cnt_rows else len(items)
    else:
        by_kind: dict[str, list[dict]] = {}
        for k in target_kinds:
            k_conds = conds + ["r.kind=?"]
            k_params = params + [k]
            where = " AND ".join(k_conds)
            if terms:
                match = " OR ".join('"' + t.replace('"', "") + '"' for t in terms)
                k_rows = run_q(
                    f"""SELECT {CARD_COLS} FROM resources_fts f JOIN resources r ON r.id=f.rowid
                        WHERE resources_fts MATCH ? AND {where}
                        ORDER BY bm25(resources_fts) - COALESCE(r.eval_score, 50) / 100.0 - (r.trial_ok IS 1) * 0.5 LIMIT ?""",
                    (match, *k_params, limit * 2)
                )
            else:
                k_rows = run_q(
                    f"""SELECT {CARD_COLS} FROM resources r WHERE {where}
                        ORDER BY COALESCE(r.first_seen, 0) DESC, r.id DESC LIMIT ?""",
                    (*k_params, limit * 2)
                )
            by_kind[k] = _diverse_hosts(k_rows, limit, per_host=per_host)

        interleaved = []
        max_len = max((len(v) for v in by_kind.values()), default=0)
        for i in range(max_len):
            for k in target_kinds:
                if i < len(by_kind[k]):
                    interleaved.append(by_kind[k][i])
                    if len(interleaved) >= limit:
                        break
            if len(interleaved) >= limit:
                break
        items = _exact_name_first(q_clean, interleaved, [r for rows in by_kind.values() for r in rows], limit)
        where_all = " AND ".join(conds)
        cnt_rows = (store.query(f"""SELECT COUNT(*) AS c FROM resources_fts f CROSS JOIN resources r
                    WHERE r.id=f.rowid AND resources_fts MATCH ? AND {where_all}""",(match,*params)) if terms else
                    store.query(f"SELECT COUNT(*) AS c FROM resources r WHERE {where_all}", params))
        total = cnt_rows[0]["c"] if cnt_rows else len(items)

    # Project one coherent page under the reentrant store lock. Hundreds of
    # individual evidence reads otherwise compete with every collector worker.
    from .content_policy import hidden_from_public_list
    items = [r for r in items if not hidden_from_public_list(r, q_clean)]
    with store._lock:
        cards = [_card_data(r,store) for r in items]
    res = {
        "query": q_clean,
        "terms": terms,
        "total": total,
        "total_is_estimate": bool(terms or has_report or verified),
        "items": cards,
    }
    if has_report:
        res['has_report'] = True
        rejected = len(res['items'])
        res['items'] = [item for item in res['items'] if item.get('report_count',0)>0]
        res['total'] = max(len(res['items']),res['total']-(rejected-len(res['items'])))
    if verified:
        res['verified'] = True
        rejected = len(res['items'])
        res['items'] = [item for item in res['items'] if item.get('connection_readiness',{}).get('verified_callable')]
        res['total'] = max(len(res['items']),res['total']-(rejected-len(res['items'])))
    if cacheable and redis_hub.is_available():
        redis_hub.set_json(redis_explore_key, res, ttl_seconds=120)
    if cacheable:
        with _front_explore_cache_lock:
            if cache_key not in _front_explore_cache and len(_front_explore_cache) >= 256:
                _front_explore_cache.pop(next(iter(_front_explore_cache)), None)
            _front_explore_cache[cache_key] = (now, res)
    return res


