def _format_mcp_result(res: dict) -> str:
    if not isinstance(res, dict):
        return str(res)
    content = res.get("content")
    if isinstance(content, list):
        texts = []
        for item in content:
            if isinstance(item, dict) and item.get("type") == "text":
                texts.append(str(item.get("text", "")))
            elif isinstance(item, str):
                texts.append(item)
            else:
                texts.append(json.dumps(item, ensure_ascii=False))
        if texts:
            return "\n".join(texts)
    return json.dumps(res, ensure_ascii=False, indent=2)


def _format_a2a_result(res: dict) -> str:
    if not isinstance(res, dict):
        return str(res)
    msg = res.get("message")
    if isinstance(msg, dict):
        parts = msg.get("parts")
        if isinstance(parts, list):
            texts = []
            for p in parts:
                if isinstance(p, dict) and "text" in p:
                    texts.append(str(p["text"]))
                elif isinstance(p, str):
                    texts.append(p)
            if texts:
                return "\n".join(texts)
    return json.dumps(res, ensure_ascii=False, indent=2)


def get_safe_agent_detail(store: Store, rid: int) -> dict:
    """Safe public metadata only for front drawer.
    Strictly excludes history (50 health check records) and admin management actions."""
    if rid in FRONT_TESTBENCH_PRESETS:
        return {"agent": FRONT_TESTBENCH_PRESETS[rid]}
    # 11-05 security review: ids outside BIGINT overflowed in the driver and answered 500.
    if not 1 <= rid <= 9223372036854775807:
        raise HTTPException(404, "Agent not found. Search with GET /api/explore?q=<task> to get current agent ids.")
    rows = store.query("SELECT * FROM resources WHERE id=?", (rid,))
    if not rows:
        raise HTTPException(404, "Agent not found. Search with GET /api/explore?q=<task> to get current agent ids.")
    r = dict(rows[0])
    if policy_excluded(r):
        raise HTTPException(404, "Agent not found. Search with GET /api/explore?q=<task> to get current agent ids.")
    raw_url = str(r.get("url") or "")
    gw_url = gateway_agent_url(rid, r.get("kind"))
    for k in ("details", "auth_info", "usage_guide", "trial_info", "eval_info"):
        val = r.get(k)
        if isinstance(val, str):
            try:
                r[k] = json.loads(val)
            except Exception:
                pass
    # Allow only the public product fields; internal discovery/authentication records stay private.
    allowed = ('id','kind','name','description','category','active','health_status','eval_grade','eval_score',
               'eval_at','trial_ok','cap_tool_count','first_seen','last_ok_at','last_check_at','auth_required',
               'auth_method','auth_observed','price_usdc','calls_30d','report_grade','report_score','url')
    resource = r
    r = {key:resource[key] for key in allowed if key in resource}
    from ..gateway.crawler import test_networks_only
    if resource.get('kind') == 'x402' and test_networks_only(resource.get('networks')):
        r['price_note'] = 'testnet_only'  # paid only in test USDC: never shown as a real price (11-10)
    r['active'] = bool(resource.get('active'))
    r['catalog_status'] = ('live' if r['active'] and resource.get('health_status')
                           in ('healthy','reachable') and resource.get('eval_security') != 'quarantine'
                           else 'historical')
    r['tools'] = []
    for spec in tools_for(resource):
        if not safe_registered_tool(spec):
            continue
        published = public_schema(spec)
        compact = usage.compact_tools([published])[0] if 'inputSchema' in published else published
        # Build generic examples from the public schema, never stored trial inputs,
        # provider defaults or private examples. IDs with no safe example stay manual.
        params = compact.get('params', {})
        required = compact.get('required', [])
        sample = usage.example_arguments({**compact, 'params': params}, resource.get('category')) if (
            isinstance(params, dict) and isinstance(required, list) and all(key in params for key in required)
        ) else None
        if sample is not None:
            try:
                validate_arguments(spec, sample)
            except ExecutionDenied:
                pass
            else:
                published['sample'] = sample
        r['tools'].append(published)
    # One copy of the tool list (11-13 PM 22:4x): usage_guide.tools repeated agent.tools, 115 of 236 KB for listing
    # 52185, and lost a deeply nested tool one level further down. Nothing in this repository read it.
    r['usage_guide'] = {'endpoint':gw_url,'tools_ref':'agent.tools'}

    # Filter subject bindings before pagination so bad imports cannot hide
    # legitimate older history behind the drawer's five-report limit.
    report_subject = store.resource(rid)
    report_rows = _trusted_report_rows(store,report_subject)
    test_reports = []
    from .report_projection import public_report
    for row in report_rows[:5]:
        report = store.get_test_report(row['id'])
        if report is None:continue
        item=public_report(report,resource,store=store)
        if item is not None:test_reports.append(item)

    r["test_reports"] = test_reports
    r["test_report"] = test_reports[0] if test_reports else None
    r["report_count"] = len(report_rows)
    pub = public_agent(r, resource,store=store)
    pub["url"] = gw_url
    pub["usage_endpoint"] = gw_url
    return {"agent": pub}


def _normalize_ui_network(net: str | None) -> str:
    if not net:
        return "base"
    nl = str(net).strip().lower()
    if "solana" in nl:
        return "solana"
    if nl in ("ethereum", "mainnet", "eip155:1"):
        return "ethereum"
    return "base"


def find_existing_agent(
    store: Store | None,
    raw_url: str,
    kind: str | None = None,
    card_url: str | None = None,
) -> dict | None:
    """Find an already-registered agent matching raw_url or its canonical variants."""
    if store is None:
        return None
    u = str(raw_url or "").strip()
    if not u:
        return None
    u_no_slash = u.rstrip("/")
    u_slash = u_no_slash + "/"
    url_candidates = {u, u_no_slash, u_slash}

    for suffix in ("/.well-known/agent-card.json", "/.well-known/agent.json"):
        if u_no_slash.endswith(suffix):
            base_u = u_no_slash[: -len(suffix)]
            if base_u:
                url_candidates.update({
                    base_u,
                    base_u + "/",
                    base_u + "/.well-known/agent-card.json",
                    base_u + "/.well-known/agent.json",
                })
            break
    else:
        if kind in (None, "a2a") and not u_no_slash.endswith(".json"):
            url_candidates.update({
                u_no_slash + "/.well-known/agent-card.json",
                u_no_slash + "/.well-known/agent.json",
            })

    if card_url:
        cu = str(card_url).strip()
        if cu:
            url_candidates.add(cu)
            url_candidates.add(cu.rstrip("/"))

    target_kinds = [kind] if kind in KINDS else list(KINDS)
    key_candidates = {f"{k}:{cand}" for k in target_kinds for cand in url_candidates if cand}

    u_list = [c for c in url_candidates if c]
    k_list = [k for k in key_candidates if k]
    if not u_list and not k_list:
        return None

    ph_u = ",".join("?" for _ in u_list)
    ph_k = ",".join("?" for _ in k_list)
    native = getattr(store, 'find_existing_candidates', None)
    rows = (native(u_list, k_list, u, u_no_slash) if callable(native) else store.query(
        f"""SELECT id, name, kind, source, url, category, description,
                   price_usdc, pay_to, method, networks, health_status
            FROM resources
            WHERE url IN ({ph_u}) OR key IN ({ph_k})
            ORDER BY active DESC, CASE WHEN url IN (?, ?) THEN 0 ELSE 1 END, id ASC
            LIMIT 1""",
        (*u_list, *k_list, u, u_no_slash),
    ))
    if not rows:
        return None
    r = dict(rows[0])
    # If kind was not constrained (e.g. during initial inspect) and raw_url is a non-card URL,
    # only match A2A well-known suffix candidates when the resource is actually A2A or exact URL matched.
    if kind in ("mcp", "x402") and r["url"] not in (u, u_no_slash, u_slash) and r["kind"] == "a2a":
        return None
    return r


def _extract_x402_info(resp, parsed, method: str = "GET") -> dict | None:
    from .registration_inspection import payment
    return payment(resp, parsed, method)


def _try_parse_a2a_card(resp, card_url: str) -> dict | None:
    from .registration_inspection import a2a_card
    return a2a_card(resp, card_url)


def _try_probe_mcp_or_post_x402(client, raw_url: str, parsed) -> dict | None:
    from .registration_inspection import mcp_or_payment
    return mcp_or_payment(client, raw_url, parsed)


def inspect_register_url(raw_url: str, store: Store | None = None, *, public_origin='https://agentconcierge.biz') -> dict:
    from .registration_inspection import inspect
    return inspect(raw_url, store, public_origin=public_origin)


def submit_register_agent(store: Store, data: dict, client_ip: str, *, public_origin='https://agentconcierge.biz') -> dict:
    """Confirm public protocol readiness and persist the private consent receipt."""
    from .registration_service import register
    return register(store, data, client_ip, public_origin=public_origin)


def get_recent_registered_agents(store: Store) -> list[dict]:
    """List recently manually registered agents."""
    rows = store.query(
        """SELECT id, kind, source, name, url, category, health_status, first_seen
           FROM resources WHERE source='manual' ORDER BY first_seen DESC LIMIT 20"""
    )
    out = []
    for r in rows:
        d = dict(r)
        gw_url = gateway_agent_url(d.get("id"), d.get("kind"))
        d["url"] = gw_url
        d["usage_endpoint"] = gw_url
        out.append(d)
    return out


def clear_front_caches(store: Store | None = None):
    from .insights_snapshot import reset as reset_insights_snapshot
    reset_insights_snapshot()   # the next read goes back to the file (or the computation when there is none)
    _front_insights_cache["at"] = 0.0
    _front_insights_cache["data"] = None
    _front_insights_cache["store_id"] = None
    _snapshot_overview_cache["at"] = 0.0
    _snapshot_overview_cache["data"] = None
    _snapshot_overview_cache["store_id"] = None
    _front_explore_cache.clear()
    _explore_result_cache.clear()
    with _bootstrap_snapshot_cache["lock"]:
        _bootstrap_snapshot_cache["at"] = 0.0
        _bootstrap_snapshot_cache["data"] = None
        _bootstrap_snapshot_cache["json"] = None
        _bootstrap_snapshot_cache["store_id"] = None
        _bootstrap_snapshot_cache["revalidating"] = False
    redis_hub = RedisHub.get_instance()
    if redis_hub.is_available():
        pfx = _redis_cache_prefix(store)
        redis_hub.delete_keys(f"{pfx}cache:overview:v2", f"{pfx}cache:insights", "a2a:cache:overview", "a2a:cache:insights")
        redis_hub.delete_pattern(f"{pfx}cache:explore:*")
        if pfx != "a2a:":
            redis_hub.delete_pattern("a2a:cache:explore:*")
        if store is None or "a2a:test:" in pfx:
            redis_hub.delete_pattern("a2a:test:*")


