    @router.get("/", include_in_schema=False)
    async def root(request: Request):
        accept = request.headers.get("accept") or ""
        from .conditional_http import prefers_markdown
        if prefers_markdown(accept):
            content = await run_in_threadpool(llms_full_txt, front.base(request), front.live_counts(), front.daily_statistics.read())
            return PlainTextResponse(content, media_type='text/markdown', headers={'Vary':'Accept','Cache-Control':'no-store'})
        if "text/html" in accept and "application/json" not in accept.split(",")[0]:
            # The page shell does not wait for catalog counts or expose a
            # personalized visitor greeting. Existing APIs hydrate missing data.
            ip = front.security.resolve_ip(request)
            front.book.record_hit(fingerprint(ip, request.headers.get('user-agent')),
                                  request.headers.get('user-agent'), request.url.path)
            body = {'greeting': 'Describe your task to find up to three relevant agents.'}
            base_url = front.base(request)
            from .public_metadata import graph, apply_daily_home
            import asyncio
            bootstrap_str, snapshot = await asyncio.gather(
                run_in_threadpool(front.html_bootstrap.read),
                run_in_threadpool(front.daily_statistics.read))
            ld_graph = graph('overview', base_url, snapshot)
            ld = json.dumps(ld_graph)
            esc = html_lib.escape
            from .pearl_view import public_page_available, default_public_page
            if public_page_available():
                page = default_public_page(bootstrap_str, ld, snapshot=snapshot,
                                           workspace_available=workspace_access_enabled and workspace_link_enabled)
                page.headers['Vary'] = 'Accept'
                return page
            from .bootstrap_delivery import compact_shell
            from ..customer_identity_view import workspace_shell
            page = compact_shell(workspace_shell(HTML, workspace_access_enabled and workspace_link_enabled)).replace("{notice}", esc(NOTICE)).replace("{ld}", ld.replace("<", "\\u003c")).replace("{greeting}", esc(body["greeting"])).replace("{base}", esc(base_url)).replace("{bootstrap_json}", bootstrap_str)
            from .daily_metadata_runtime import daily_metadata_runtime
            page = daily_metadata_runtime(apply_daily_home(page, snapshot))
            nonce = secrets.token_urlsafe(32)
            from .bootstrap_delivery import nonce_scripts
            page = nonce_scripts(page,nonce)
            csp = SECURITY_HEADERS["Content-Security-Policy"].replace("script-src 'none'", f"script-src 'nonce-{nonce}'") + "; worker-src 'self'"
            return HTMLResponse(page, headers={"Content-Security-Policy": csp, "Vary": "Accept"})
        # One URL answers in HTML, Markdown or JSON, so shared caches must key on Accept.
        return JSONResponse(jsonable_encoder(await run_in_threadpool(front.welcome, request)), headers={'Vary': 'Accept'})

