    @router.post("/unsubscribe")
    async def unsubscribe(request: Request):
        ip = front.security.resolve_ip(request)
        if getattr(front, "security", None):
            if not front.security.allow_inquiry(ip, base_limit=20):
                raise HTTPException(429, "Too many cancellation requests. Please try again later.")

        raw_token = _token_from(request)
        body = {}
        try:
            body = await read_json_object(request)
        except Exception:
            pass
        if not raw_token and isinstance(body, dict) and body.get("token"):
            raw_token = str(body.get("token")).strip()[:128]

        v = front.book.by_token(raw_token) if raw_token else None
        if v is None:
            return JSONResponse({"audience": AUDIENCE, "error": "Send your visitor token as the X-Visitor-Token header."}, status_code=401)

        front.book.set_notify(v.id, False)
        front.updates.stop_all(v.id)

        reason = str(body.get("reason", ""))[:200] if isinstance(body, dict) else ""
        source = str(body.get("source", "ftc_footer"))[:50] if isinstance(body, dict) else "ftc_footer"
        user_agent = request.headers.get("user-agent", "")[:200]
        token_masked = (raw_token[:6] + "..." + raw_token[-4:]) if (raw_token and len(raw_token) > 10) else raw_token
        token_hash = hashlib.sha256(raw_token.encode("utf-8")).hexdigest() if raw_token else None

        req_id = front.store.record_cancellation_request(
            visitor_id=v.id,
            visitor_token_hash=token_hash,
            token_masked=token_masked,
            source=source,
            reason=reason or "1-Click Unsubscribe via FTC footer standard",
            ip=None,
            user_agent=None  # 11-10: no address or user agent stored
        )

        return {"audience": AUDIENCE, "ok": True, "request_id": req_id, "reply": "Done — no more messages. Say \"resume\" to turn them back on."}

