    @router.post("/api/privacy/opt-out")
    async def api_privacy_opt_out(request: Request):
        """Record a preference or receive a request for a separately reviewed action."""
        ip = front.security.resolve_ip(request)
        user_agent = request.headers.get("user-agent", "")[:200]
        token = _token_from(request)
        token_masked = (token[:6] + "..." + token[-4:]) if (token and len(token) > 10) else None

        if getattr(front, "security", None):
            allowed = front.security.allow_feature(ip, 'privacy_request', 15)
            from .security import quota_headers
            request.scope['agent_adoption_quota'] = quota_headers()
            if not allowed:
                raise HTTPException(429, "Too many privacy requests. Please try again shortly.", headers={"Retry-After":"60"})
            from .security import quota_headers
            request.scope['agent_adoption_quota'] = quota_headers()

        from ..privacy_requests import initial_status, parse_request
        if request.headers.get('content-type', '').split(';', 1)[0].strip().lower() != 'application/json':
            raise HTTPException(415, "Content-Type must be application/json.")
        try:
            body = parse_request(await read_body(request))
        except ValueError as exc:
            raise HTTPException(400, str(exc)) from exc
        if set(body) - {'request_type', 'email', 'details', 'gpc'}:
            raise HTTPException(422, "Unsupported privacy request fields.")
        request_type = body.get("request_type")
        if not isinstance(request_type, str):
            raise HTTPException(422, "Unsupported privacy request type.")
        try:
            status = initial_status(request_type)
        except ValueError as exc:
            raise HTTPException(422, str(exc)) from exc
        email, details = body.get('email', ''), body.get('details', '')
        if not isinstance(email, str) or len(email) > 150 or not isinstance(details, str) or len(details) > 2000:
            raise HTTPException(422, "Invalid privacy request fields.")
        email, details = email.strip(), details.strip()
        if email and not re.fullmatch(r'[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+', email):
            raise HTTPException(422, "A valid contact email is required.")
        if status == 'pending_verification':  # 11-10: access, correction and deletion requests go by email
            return JSONResponse({"ok": False, "email": "contact@agentconcierge.biz", "error": "Email contact@agentconcierge.biz for access, correction or deletion requests. This site does not store contact details."}, status_code=410,
                                headers={"Cache-Control": "no-store"})
        if 'gpc' in body and type(body['gpc']) is not bool:
            raise HTTPException(422, "The privacy signal must be a boolean.")
        gpc_detected = int(request.headers.get("sec-gpc") == "1" or body.get('gpc', False))

        req_id = front.store.record_privacy_request(
            request_type=request_type,
            visitor_token_masked=token_masked,
            email=None,  # 11-10: contact details are not stored; reviewed requests go by email
            details=details or ("One-click CCPA / GPC opt-out registered from web client" if request_type == "ccpa_opt_out" else details),
            ip=None,
            user_agent=None,
            gpc_detected=gpc_detected,
            statutory_days=45
        )

        return {
            "ok": True,
            "request_id": req_id,
            "status": status,
            "statutory_days": 45,
            "gpc_detected": bool(gpc_detected),
            "message": "Your privacy request was received. Any requested data action requires separate verification and review."
        }

