    @router.get("/api/explore")
    def api_explore(request: Request, q: str = Query("", max_length=500), kind: str | None = None,
                    category: str | None = None, verified: bool = False, no_auth: bool = False,
                    has_report: bool = False,
                    limit: int = Query(45, ge=1, le=300),
                    offset: int = Query(0, ge=0, le=299),
                    cursor: str | None = Query(None, max_length=8, pattern=r'^o[0-9]{1,3}$')):
        if cursor is not None:
            # An opaque page cursor from next_cursor; it names the same bounded window as offset.
            offset = int(cursor[1:])
            if offset > 299:
                raise HTTPException(422, "cursor is outside the result window.")
        ip = front.security.resolve_ip(request)
        if not front.security.allow_explore(ip, base_limit=120):
            front.security.record_violation(ip, "rate_limit_429", request.url.path, request.method, request.headers.get("user-agent"), "Explore limit exceeded")
            raise HTTPException(429, "Search limit reached. Please slow down.", headers={"Retry-After": "60"})
        from .protocols import requested_protocol
        try:
            kind = requested_protocol(q, {'kind': kind})
        except ValueError as error:
            raise HTTPException(422, str(error)) from error
        from .discovery import enabled
        from .explore_search import page, browse_query
        window_limit = min(300, offset + limit + 1)
        # Directory terms browse the selected catalog; never claim arbitrary task matches.
        ignored = browse_query(q)
        from .explore_search import corrected_task
        # Curated misspellings (translte, gihtub) are never real words, so search the fix and say so.
        fixed = None if ignored else corrected_task(q.strip())
        effective = '' if ignored else fixed or q
        started = time.monotonic()
        if not has_report and (getattr(front.store,'backend',None)=='postgresql' or (effective.strip() and enabled(front.rag_engine))):
            key = explore_cache_key(front, effective, kind, category, verified, no_auth, window_limit)
            if offset == 0 and kind is None and category is None and not verified and not no_auth:
                _explore_popularity.record(effective)
            def compute(window=window_limit):
                from .hybrid_explore import scoped_explore
                return scoped_explore(front.store,front.rag_engine,effective,kind,category,verified,no_auth,window)
            shared_hit=[]
            result=_explore_result_cache.complete(key)
            reused=result is not None
            if result is None:
                result,reused=_explore_result_cache.load(key,_shared_explore(front.store,key,compute,shared_hit))
            if reused or shared_hit:result=_timed_revalidation(front.store,result)
            next_window=min(300,offset+2*limit+1)
            if (getattr(front.store,'backend',None)=='postgresql'
                    and result.get('complete') is False and next_window>window_limit
                    and len(result.get('items') or ())>=offset+limit):
                # Load More asks for exactly this window; compute it while the visitor reads.
                _next_page_prefetch.submit(key[:-1]+(next_window,),_shared_explore(
                    front.store,key[:-1]+(next_window,),lambda:compute(next_window),[]))
        else:
            explore_key = (*explore_cache_key(front, effective, kind, category, verified, no_auth, window_limit), has_report)
            compute=lambda:get_front_explore(
                front.store,effective,kind,category,verified,no_auth,window_limit,has_report=has_report)
            shared_hit=[]
            if has_report:
                # A first report-filtered page reads thousands of report rows (seconds); share it across
                # slots and restarts. The marker sits before the window so no key equals a plain search's.
                compute=_shared_explore(front.store,explore_key[:-2]+('has_report',window_limit),compute,shared_hit)
            result,reused=_explore_result_cache.load(explore_key,compute)
            if reused or shared_hit:result=_timed_revalidation(front.store,result)
        result = _continue_snapshot((effective, kind, category, verified, no_auth, has_report), result, offset, limit)
        body = page(result, offset, limit)
        body.pop('complete', None)  # an internal cache fact, not part of the public response
        if ignored:
            body = {**body, 'query': q.strip()[:500], 'query_ignored': True, 'suggestions': [],
                    'status':'browsing','search_notice':'This query is broad, so the selected agent catalog is shown. Add a task, such as weather forecast or document translation, to narrow the results.'}
        if fixed:
            body = {**body, 'query': q.strip()[:500], 'corrected_query': fixed, 'suggestions': [],
                    'search_notice': f'Showing results for "{fixed}" instead of "{q.strip()[:100]}".'}
        from .hybrid_explore import ERC8004_QUERY
        if ERC8004_QUERY.fullmatch(q.strip()):
            body['search_notice']='ERC-8004 identifies an agent registry, not a task category. Add a task to find a specific capability.'
        from fastapi.encoders import jsonable_encoder
        encoded = jsonable_encoder(body)
        raw_bytes = json.dumps(encoded, sort_keys=True).encode()
        etag = f'"{hashlib.sha256(raw_bytes).hexdigest()[:16]}"'
        if request.headers.get("if-none-match") == etag:
            return Response(status_code=304, headers={
                'ETag': etag,
                'Cache-Control': 'public, max-age=30',
                'Access-Control-Allow-Origin': '*',
                'Access-Control-Expose-Headers': 'ETag, Server-Timing',
            })
        return JSONResponse(encoded, headers={
            'ETag': etag,
            'Cache-Control': 'public, max-age=30',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Expose-Headers': 'ETag, Server-Timing',
            'Server-Timing': 'explore;dur=%.0f' % ((time.monotonic() - started) * 1000)
        })

