    @router.post("/api/test/execute")
    async def api_test_execute(request: Request):
        """Inspect the actual client request and execute through the shared managed connection."""
        ip = front.security.resolve_ip(request)
        if not front.security.allow_probe(ip, base_limit=10):
            raise HTTPException(429, "Too many test execution requests.", headers={"Retry-After":"60"})
        body = await read_json_object(request)
        rid = body.get('resource_id')
        if type(rid) is not int or not -(2**31)<rid<2**31:
            raise HTTPException(400,'resource_id (integer) is required.')
        if set(body)-{'resource_id','tool','arguments','message','timeout_seconds'}:
            raise HTTPException(400,'Unsupported test parameters.')
        args=body.get('arguments',{})
        tool=body.get('tool','');message=body.get('message','')
        if not isinstance(args,dict) or not isinstance(tool,str) or not isinstance(message,str):
            raise HTTPException(400,'Invalid tool, arguments or message.')
        try:
            raw=body.get('timeout_seconds',10)
            if isinstance(raw,bool):raise ValueError()
            timeout=float(raw)
            if not math.isfinite(timeout):raise ValueError()
            timeout=min(max(timeout,2),8)
        except (ValueError,TypeError,OverflowError):
            raise HTTPException(400,'timeout_seconds must be a finite number.')
        started=time.monotonic()
        wire={'url':'https://agentconcierge.biz/api/test/execute','path':'/api/test/execute','method':'POST',
              'headers':{'Content-Type':'application/json'},'body':public_metadata(body),'scope':'client-to-gateway','sanitized':True}
        if rid in FRONT_TESTBENCH_PRESETS:
            result={'ok':False,'execution_succeeded':False,'transport_ok':False,'protocol_valid':False,
                    'simulated':True,'task_status':'simulation','status_code':None,
                    'protocol':FRONT_TESTBENCH_PRESETS[rid]['kind'],
                    'output':'Demo only. No provider was contacted. This sample is not live or verified.',
                    'error_message':None,'is_error':False}
        else:
            try:
                result=await front.managed_gateway.execute(rid,tool=tool,arguments=args,message=message,timeout=timeout,source='testbench')
            except ExecutionDenied as exc:
                return JSONResponse({'detail':str(exc),'error_code':exc.error_code,
                                     'correlation_id':exc.correlation_id},status_code=400)
            except HTTPException as exc:
                if not getattr(exc,'correlation_id',None):raise
                return JSONResponse({'detail':exc.detail,'error_code':exc.error_code,
                                     'correlation_id':exc.correlation_id},status_code=exc.status_code,headers=exc.headers)
        result.update(latency_scope='gateway-operation',latency_ms=round((time.monotonic()-started)*1000,1),tested_at=time.time(),
                      request_wire=wire,response_wire={'scope':'gateway-result','simulated':result['simulated'],
                      'transport_ok':result['transport_ok'],'protocol_valid':result['protocol_valid'],
                      'task_status':result['task_status'],'execution_succeeded':result['execution_succeeded'],
                      'result':result['output']})
        if not isinstance(result['output'],str):result['output']=json.dumps(result['output'],ensure_ascii=False,indent=2)
        return result

    @router.post("/api/register/inspect")
    async def api_register_inspect(request: Request):
        ip = front.security.resolve_ip(request)
        allowed = front.security.allow_feature(ip, 'registration_inspect', 10)
        from .security import quota_headers
        request.scope['agent_adoption_quota'] = quota_headers()
        if not allowed:
            front.security.record_violation(ip, "rate_limit_429", request.url.path, request.method, request.headers.get("user-agent"), "Inspect probe limit exceeded")
            raise HTTPException(429, "Too many probe requests. Please wait a moment.", headers={"Retry-After": "60"})
        try:
            data = await read_json_object(request)
        except Exception:
            raise HTTPException(400, "Valid JSON required.")
        from .registration_policy import text_field
        url = text_field(data.get("url"), "url", 1, 1000)
        if not url:
            raise HTTPException(400, "URL is required.")
        if not url.startswith(("http://", "https://")):
            raise HTTPException(400, "URL must begin with http:// or https://")
        if len(url) > 1000:
            raise HTTPException(400, "URL length exceeds limit (maximum 1000 characters).")
        bad, reason = check_malicious_text(url)
        if bad:
            front.security.record_violation(ip, "injection_attempt", request.url.path, request.method, request.headers.get("user-agent"), f"Inspect URL validation failed: {reason}")
            raise HTTPException(400, f"Security validation failed for URL: {reason}")
        return await run_in_threadpool(inspect_register_url, url, front.store, public_origin=front.public_url or "https://agentconcierge.biz")

