    @router.get('/api/workflows/{template_id}/webapp')
    async def api_workflow_webapp(template_id: int, req: Request):
        from ..workflow_webapp import export_config, build_package
        from ..workflows import public_template
        headers = workflow_cors()
        if not front.security.allow_feature(front.security.resolve_ip(req), 'workflow_webapp', 60):
            return JSONResponse({'error':'Too many downloads. Please try again shortly.'}, status_code=429, headers=headers)
        if not 0 < template_id < 2**31:
            return JSONResponse({'error':'Published workflow not found.'}, status_code=404, headers=headers)
        def package():
            workflow = front.store.get_workflow(template_id)
            if not workflow:
                return None
            if front.workflows.products.known(template_id):
                from ..workflow_product_package import build_product_package
                projected=public_template(workflow,front.workflows)
                return build_product_package(projected) if projected else None
            try:
                config = export_config(workflow)
            except ValueError:
                return None
            return build_package(config)
        result = await run_in_threadpool(package)
        if result is None:
            return JSONResponse({'error':'Published workflow not found.'}, status_code=404, headers=headers)
        archive, filename = result
        return Response(archive, media_type='application/zip', headers={**headers,
            'Content-Disposition':f'attachment; filename="{filename}"',
            'X-Content-Type-Options':'nosniff'})

