    @router.post('/api/rum')
    async def api_rum(req: Request):
        # Field Core Web Vitals beacon (rum.py). Nothing identifying is stored; a bad or limited beacon is dropped quietly.
        from . import rum
        if front.security.allow_feature(front.security.resolve_ip(req), 'rum', 30):
            try:
                rum.record(await read_body(req))
            except (rum.RumError, OSError):
                pass
        return Response(status_code=204)

    # ---------------- A2A ----------------
    async def run_admitted_call(request, v, rid_val, tool_val, call_args, *, task_str="", account_id=None,
                                payment_info=None, idempotency_key=None, edge_mode=None, service=None):
        """Run one admitted tool through the gateway and record the outcome, as the MCP `call` tool does.

        11-14 (PM 04:0x): the A2A "run" command uses this same path, so both share the gateway admit, the
        execution policy (relay verbs, read-only, action tools blocked), timeouts, outcome records and recovery.
        Returns (ok, execution, reply text, structured content)."""
        from ..edge_gateway.machine import execute as execute_ticket
        alternative = None
        exec_res = await run_in_threadpool(execute_ticket, front, rid_val, tool_val, call_args,
            principal=v.id, idempotency_key=idempotency_key, payment=payment_info,
            **({'stored_run':edge_mode['run_id']} if edge_mode and edge_mode['mode']=='result' else {}))
        if edge_mode and edge_mode['mode']=='result':
            if exec_res is None:
                from ..edge_gateway.machine import refused
                exec_res = refused(unknown=True)
            elif exec_res.get('ok'):
                from ..edge_gateway.result_transport import load_result
                request.scope['edge_result_sources'] = [await run_in_threadpool(load_result, service, edge_mode['run_id'])]
        if exec_res is None:
            exec_res = await run_in_threadpool(front.proxy.execute, rid_val, tool_val, call_args, account_id, payment_info, public=True)
        if exec_res.get('error_code') in ('UPSTREAM_TIMEOUT', 'UPSTREAM_NETWORK', 'UPSTREAM_PROTOCOL'):
            exec_res['retry_safe'] = False
        bound_resource=front.store.resource(rid_val) or {}
        exec_res=project(public_metadata(exec_res),gateway_agent_url(rid_val,bound_resource.get('kind')),bindings(bound_resource))
        if not exec_res.get('ok') and not exec_res.get('payment_required'):
            from .execution_errors import fields as execution_failure_fields
            exec_res['error']=('The execution outcome is unconfirmed. Keep this request paused for review.'
                if exec_res.get('retry_safe') is False else execution_failure_fields(exec_res.get('error_code'))['error_message'])
        ok_val = exec_res.get("ok", False)
        if not ok_val and not exec_res.get('payment_required'):
            # How to get past it, with the tool's required arguments for bad input (growth plan 7 item 4).
            from .execution_errors import fix_for
            from .execution_policy import tools_for
            try:
                spec = next((t for t in (tools_for(bound_resource) if bound_resource else [])
                             if isinstance(t, dict) and t.get('name') == tool_val), None)
            except Exception:   # the fix line is advice; it never turns a failure answer into a server error
                spec = None
            exec_res['fix'] = fix_for('UPSTREAM_TIMEOUT' if exec_res.get('retry_safe') is False
                                      else exec_res.get('error_code'), spec, exec_res.get('retry_after'))
        request.scope['traffic_gateway'] = {'step': 'execute', 'ok': bool(ok_val), 'rid': rid_val}
        alternative = None

        if (bound_resource and isinstance(rid_val,int) and not exec_res.get('payment_required')
                and (ok_val or exec_res.get('retry_safe') is not False and exec_res.get('error_code') in ('UPSTREAM_TOOL_ERROR','EXECUTION_FAILED'))):
            if v:
                await run_in_threadpool(front.book.record_outcome, v, rid_val, ok_val)
                last_rid, last_tool = await run_in_threadpool(front.book.get_last_tool, v.id)
                if last_rid and last_tool:
                    await run_in_threadpool(front.inertia.record_transition, last_rid, last_tool, rid_val, tool_val)
                await run_in_threadpool(front.book.save_last_tool, v, rid_val, tool_val)
            with front.store.tx() as db:
                db.execute(
                    "INSERT INTO feedback (need_id, resource_id, success, rating, created) VALUES (?, ?, ?, ?, ?)",
                    (f"mcp_{uuid.uuid4().hex[:8]}", rid_val, int(ok_val), 5 if ok_val else 1, time.time())
                )

        prefetched = []
        code_template = None
        recovery = {'alternatives': [], 'workflows': []}
        if not ok_val and not exec_res.get("payment_required") and exec_res.get('retry_safe') is not False:
            search_task = task_str
            if not search_task and v:
                interests = front.book.interests(v.id)
                if interests:
                    search_task = interests[0]["task"]
            if not search_task:
                search_task = tool_val.replace("_", " ")
            from .recovery import alternatives as recover_alternatives
            recovery = await run_in_threadpool(recover_alternatives, front, v, rid_val, search_task)
            alternative = recovery['alternative']
        elif isinstance(rid_val, int) and ok_val:
            # Suggest optional next tools from recorded usage and affinities.
            from .recovery import session_task
            _, suggestion_protocol = await run_in_threadpool(session_task, front, v)
            suggestion_excluded = await run_in_threadpool(front.book.failed_resources, v.id) if v else set()
            prefetched = await run_in_threadpool(front.inertia.predict_next, rid_val, tool_val, limit=2,
                protocol=suggestion_protocol, exclude=suggestion_excluded)
            projected_hints = []
            for hint in prefetched:
                target = front.store.resource(hint.get('resource_id')) or {}
                if target.get('kind') in KINDS:
                    projected_hints.append(project(public_metadata(hint),
                        gateway_agent_url(target['id'], target['kind']), bindings(target)))
            prefetched = projected_hints
            if prefetched:
                chain = [{"resource_id": rid_val, "name": tool_val}] + prefetched
                code_template = front.inertia.generate_code_mode_template(chain, base_url=f"{front.base(request)}/mcp")

        pay_note = ""
        if exec_res.get("payment"):
            pay_st = exec_res["payment"]
            if pay_st.get("status") == "settled":
                pay_note = f"\n[Clearinghouse] Paid {pay_st.get('amount')} micro-USDC (SLA verified, tx: {pay_st.get('tx_id')})"
            elif pay_st.get("status") == "refunded":
                pay_note = f"\n[Clearinghouse] Payment refunded: {pay_st.get('amount')} micro-USDC (reason: {pay_st.get('reason')})"

        if ok_val:
            out_sample = exec_res.get("sample_output") or json.dumps(exec_res.get("result", {}), ensure_ascii=False)
            next_info = ""
            if prefetched:
                names_p = [f"{p['tool']['name']} (p={p['probability']})" for p in prefetched]
                next_info = f"\n\n[Next-tool suggestions] Next recommended tools: {', '.join(names_p)}"
            reply_text = f"Tool '{tool_val}' on resource {rid_val} executed successfully ({exec_res.get('latency_ms', 0)}ms):\n{out_sample[:500]}{pay_note}{next_info}"
        else:
            err_msg = exec_res.get("error") or "execution failed"
            if exec_res.get('retry_safe') is False:
                reply_text = f"The outcome of '{tool_val}' on resource {rid_val} is unconfirmed. Keep this request paused for review."
            elif exec_res.get("payment_required"):
                reply_text = f"Payment Required for resource {rid_val}: {err_msg}"
            elif alternative:
                reply_text = (f"Execution of '{tool_val}' on resource {rid_val} failed: {err_msg}{pay_note}\n"
                              f"Self-reflection alternative found: {alternative['name']} ({alternative['url']}).")
            else:
                reply_text = f"Execution of '{tool_val}' on resource {rid_val} failed: {err_msg}{pay_note}"
            if exec_res.get('fix'):
                reply_text += f"\nHow to fix: {exec_res['fix']}"

        structured = {
            "intent": "call",
            "ok": ok_val,
            "resource_id": rid_val,
            "tool": tool_val,
            "execution": exec_res,
            "alternative": alternative,
            "alternatives": recovery.get('alternatives', []),
            "workflows": recovery.get('workflows', []),
            "prefetched_tools": prefetched,
            "code_mode_template": code_template,
            "visitor": front.visitor_info(v) if v else None,
        }
        return ok_val, exec_res, reply_text, structured

    @router.post("/a2a")
    @router.post("/a2a/", include_in_schema=False)
    async def a2a(request: Request):
        if (r := limited(request)) is not None:
            return r
        version = request.headers.get("a2a-version")
        if version is not None and version.strip() not in A2A_VERSIONS:
            # A2A VersionNotSupportedError; the request is not processed.
            return {"jsonrpc": "2.0", "id": None, "error": {"code": -32009,
                    "message": "Unsupported A2A-Version. Supported: " + ", ".join(A2A_VERSIONS) + "."}}
        try:
            req = json.loads(await read_body(request))
        except (ValueError, RecursionError):
            return JSONResponse({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error"}})
        from .jsonrpc_contract import envelope_error
        if error := envelope_error(req):
            return {"jsonrpc": "2.0", "id": req.get('id') if isinstance(req, dict) and error['code'] == -32602 else None, "error": error}
        rid, method, params = req.get("id"), req.get("method"), req.get("params", {})
        if not isinstance(params, dict) or not isinstance(method, str):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "method must be a string and params must be an object."}}
        if method in ("tasks/get", "GetTask", "tasks/cancel", "CancelTask"):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32001, "message": "Task not found (I answer with messages, not tasks)"}}
        if method not in ("message/send", "SendMessage"):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32601, "message": f"Method not found: {method}. Use message/send or SendMessage."}}
        msg = params.get("message") if isinstance(params, dict) else None
        if not isinstance(msg, dict):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "params.message is required"}}
        texts, data = [], {}
        parts = msg.get("parts", [])
        if not isinstance(parts, list) or not parts:
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "message.parts must be a non-empty array."}}
        for p in parts:
            if not isinstance(p, dict):
                continue
            if isinstance(p.get("text"), str):
                texts.append(p["text"])
            d = p.get("data")
            if isinstance(d, dict):
                data.update(d["data"] if set(d) == {"data"} and isinstance(d["data"], dict) else d)
        meta = msg.get("metadata") if isinstance(msg.get("metadata"), dict) else {}
        token = meta.get("visitor_token") or data.pop("visitor_token", None)
        name = meta.get("agent_name") or data.pop("agent_name", None)
        ctx = msg.get("contextId") if isinstance(msg.get("contextId"), str) else None
        if 'contextId' in msg and (ctx is None or not ctx or len(ctx)>200):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Provide a non-empty contextId of at most 200 characters."}}
        from . import necklace_surface
        necklace_reply = await run_in_threadpool(necklace_surface.a2a_answer, front,
                                                 "\n".join(texts).replace("\x00", "")[:MAX_MESSAGE], front.base(request))
        if necklace_reply is not None:  # 11-14: "run necklace <slug> {...}" (A2A skill necklace-<slug>)
            text, payload = necklace_reply
            mid = str(uuid.uuid4())
            parts_out = ([{"text": text}, {"data": {"data": payload}}] if method == "SendMessage"
                         else [{"kind": "text", "text": text}, {"kind": "data", "data": payload}])
            message = ({"message": {"role": "ROLE_AGENT", "messageId": mid, "contextId": ctx, "parts": parts_out}}
                       if method == "SendMessage" else
                       {"kind": "message", "role": "agent", "messageId": mid, "contextId": ctx, "parts": parts_out})
            return JSONResponse({"jsonrpc": "2.0", "id": rid, "result": message})
        from . import a2a_run
        wanted = a2a_run.parse("\n".join(texts).replace("\x00", "")[:MAX_MESSAGE])
        if wanted is not None:
            # 11-14 (PM 04:0x): "run N {arguments}" runs item N we recommended in this conversation, through the
            # same path as the MCP `call` tool (run_admitted_call); nothing wider. See a2a_run.
            v = None
            if ctx:
                try:
                    v = await run_in_threadpool(front.identify, request, "a2a", token, name if isinstance(name, str) else None,
                                                ctx, create=False)
                except HTTPException as exc:
                    if exc.status_code != 400:
                        raise
            if v is None:
                text, payload = a2a_run.refusal('no_conversation')
            else:
                results, _ = await run_in_threadpool(front.book.last_results, v.id)
                chosen = await run_in_threadpool(a2a_run.choose, front, results, wanted[0], wanted[1])
                if len(chosen) == 2:
                    text, payload = chosen
                else:
                    item, run_rid, tool = chosen
                    ok, execution, reply_text, _structured = await run_admitted_call(
                        request, v, run_rid, tool, wanted[1], task_str=str(item.get('name') or ''),
                        service=getattr(front, 'edge_gateway', None))
                    text, payload = a2a_run.answer(item, run_rid, tool, ok, execution, reply_text)
                payload['visitor'] = front.visitor_info(v)
            mid = str(uuid.uuid4())
            parts_out = ([{"text": text}, {"data": {"data": payload}}] if method == "SendMessage"
                         else [{"kind": "text", "text": text}, {"kind": "data", "data": payload}])
            message = ({"message": {"role": "ROLE_AGENT", "messageId": mid, "contextId": ctx, "parts": parts_out}}
                       if method == "SendMessage" else
                       {"kind": "message", "role": "agent", "messageId": mid, "contextId": ctx, "parts": parts_out})
            return JSONResponse({"jsonrpc": "2.0", "id": rid, "result": message})
        try:
            v, reply = await run_in_threadpool(front.chat, request, "a2a", "\n".join(texts).replace("\x00", "")[:MAX_MESSAGE], data, token,
                                               name if isinstance(name, str) else None, ctx)
        except HTTPException as exc:
            if exc.status_code != 400:
                raise
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Conversation context is unavailable. Start without a contextId."}}
        first_contact = not ctx
        if not ctx:  # hand out an unguessable context so later messages in it are recognised without a token
            ctx = front.book.new_context_id()
            front.book.bind_context(v, ctx, fingerprint(front.security.resolve_ip(request),
                                                        request.headers.get("user-agent")), issued=True)
        reply=await run_in_threadpool(front.public_reply, reply)
        # 11-14 (PM 04:0x): an A2A client cannot use the MCP `call` tool; it runs a recommendation with "run N".
        reply = a2a_run.a2a_wording(reply)
        payload = {"intent": reply.intent, "suggested_replies": reply.suggested, "visitor": front.visitor_info(v), **reply.data}
        if first_contact:
            payload.setdefault("return_visit", A2A_RETURN_VISIT)
        mid = str(uuid.uuid4())
        if method == "SendMessage":
            result = {"message": {"role": "ROLE_AGENT", "messageId": mid, "contextId": ctx,
                                  "parts": [{"text": reply.text}, {"data": {"data": payload}}]}}
        else:
            result = {"kind": "message", "role": "agent", "messageId": mid, "contextId": ctx,
                      "parts": [{"kind": "text", "text": reply.text}, {"kind": "data", "data": payload}]}
        headers = {"X-Visitor-Token": v.token} if v.token else {}
        return JSONResponse({"jsonrpc": "2.0", "id": rid, "result": result}, headers=headers)

    # ---------------- MCP ----------------
    from . import mcp_tasks
    TOOLS = mcp_tools()

    def mcp_result(rid, result) -> dict:
        if isinstance(result.get('structuredContent'), dict):
            text = '\n'.join(p['text'] for p in result.get('content', []) if p.get('type') == 'text')
            result = {**result, 'structuredContent': {**result['structuredContent'], 'text': text}}
        return {"jsonrpc": "2.0", "id": rid, "result": result}

    @router.get("/mcp", include_in_schema=False)
    def mcp_get():
        return JSONResponse({"audience": AUDIENCE, "error": "POST JSON-RPC to this endpoint (no SSE stream)."}, status_code=405)

    @router.post("/mcp")
    @router.post("/mcp/", include_in_schema=False)
    async def mcp(request: Request):
        if (r := limited(request)) is not None:
            return r
        version = request.headers.get("mcp-protocol-version")
        # Checked after parsing: initialize and server/discover negotiate the version (11-11).
        unsupported_version = version is not None and version.strip() not in MCP_VERSIONS
        edge_mode = None
        try:
            raw_body = await read_body(request)
            if request.headers.get('x-edge-mcp-prepare') == 'v1':
                from ..edge_gateway.auth import verify_service
                from ..edge_gateway.state import nonce
                from ..edge_gateway.config import EdgeError
                service = getattr(front, 'edge_gateway', None)
                try:
                    if service is None or request.url.query:
                        raise EdgeError('AUTH_REQUIRED', 401)
                    identity = verify_service(service.config.key, 'POST', '/mcp', request.headers, raw_body, now=service.clock())
                    await run_in_threadpool(nonce, service.store, identity, service.clock())
                except EdgeError:
                    return JSONResponse({'error_code':'AUTH_REQUIRED'}, status_code=401)
            req = json.loads(raw_body)
            from .jsonrpc_contract import envelope_error
            if error := envelope_error(req):
                return {"jsonrpc": "2.0", "id": req.get('id') if isinstance(req, dict) and error['code'] == -32602 else None, "error": error}
            transport = req.pop('_edge_transport', None)
            if request.headers.get('x-edge-mcp-prepare') == 'v1':
                if (type(transport) is not dict or transport.get('mode') not in ('prepare', 'result')
                        or set(transport) != ({'mode'} if transport.get('mode') == 'prepare' else {'mode','run_id'})):
                    raise ValueError('Invalid transport')
                edge_mode = transport
        except (ValueError, RecursionError):
            return JSONResponse({"jsonrpc": "2.0", "id": None, "error": {"code": -32700, "message": "Parse error (batches not supported)"}})
        rid, method, params = req.get("id"), req.get("method"), req.get("params", {})
        if not isinstance(params, dict) or not isinstance(method, str):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "method must be a string and params must be an object."}}
        if unsupported_version and method not in ("initialize", "server/discover"):
            # Streamable HTTP: an unsupported protocol version header is a 400 Bad Request.
            return JSONResponse({"jsonrpc": "2.0", "id": rid, "error": {"code": -32600,
                "message": "Unsupported MCP-Protocol-Version. Supported: " + ", ".join(MCP_VERSIONS) + ".",
                "data": {"supported": list(MCP_VERSIONS), "requested": version.strip()[:40]}}}, status_code=400)
        session = request.headers.get("mcp-session-id")
        meta = (params.get("_meta") or req.get("_meta") or {}) if isinstance(params, dict) else {}
        client_meta = meta.get("io.modelcontextprotocol/clientInfo") if isinstance(meta, dict) else {}

        if method == "server/discover":
            asked = params.get("protocolVersion") if isinstance(params, dict) else None
            v = front.book.by_token(_token_from(request))
            greet = await run_in_threadpool(front.concierge.greeting, v)
            instructions = (f"{NOTICE}\n\n{greet.text}\n\nCall `search` for a read-only lookup, or `chat` to save your task. A chat reply gives you a "
                            "visitor token — pass it as `visitor_token` (or the X-Visitor-Token header) so I remember you next time.\n\n"+RETURN_VISIT)
            return JSONResponse(mcp_result(rid, {
                "protocolVersion": asked if asked in MCP_VERSIONS else MCP_VERSIONS[0],
                "supportedVersions": list(MCP_VERSIONS),
                "capabilities": {"tools": {"listChanged": False}, "tasks": mcp_tasks.CAPABILITY},
                "serverInfo": {"name": "agent-concierge", "title": "AgentValCon — Agent Value Gateway", "version": "1.0.0"},
                "instructions": instructions}))

        if method == "initialize":
            sid = uuid.uuid4().hex
            client = params.get("clientInfo", client_meta or {})
            if not isinstance(client, dict):
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "clientInfo must be an object."}}
            front.mcp_sessions[sid] = {"name": str(client.get("name") or "")[:80] or None}
            while len(front.mcp_sessions) > 2000:
                front.mcp_sessions.popitem(last=False)
            asked = params.get("protocolVersion") if isinstance(params, dict) else None
            v = front.book.by_token(_token_from(request))
            greet = await run_in_threadpool(front.concierge.greeting, v)
            instructions = (f"{NOTICE}\n\n{greet.text}\n\nCall `search` for a read-only lookup, or `chat` to save your task. A chat reply gives you a "
                            "visitor token — pass it as `visitor_token` (or the X-Visitor-Token header) so I remember you next time.\n\n"+RETURN_VISIT)
            return JSONResponse(mcp_result(rid, {
                "protocolVersion": asked if asked in MCP_VERSIONS else MCP_VERSIONS[0],
                "capabilities": {"tools": {"listChanged": False}, "tasks": mcp_tasks.CAPABILITY},
                "serverInfo": {"name": "agent-concierge", "title": "AgentValCon — Agent Value Gateway", "version": "1.0.0"},
                "instructions": instructions}), headers={"Mcp-Session-Id": sid})
        if isinstance(method, str) and method.startswith("notifications/"):
            return Response(status_code=202)
        if method == "ping":
            return mcp_result(rid, {})
        if method == "tools/list":
            if params.get('cursor') is not None:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "This bounded tool list has no continuation cursor."}}
            from .necklace_surface import tools as necklace_tools  # 11-14: offered necklaces, none while nothing is live
            return mcp_result(rid, {"tools": TOOLS + necklace_tools()})
        if method in ("tasks/get", "tasks/result", "tasks/cancel"):
            # MCP tasks follow published workflow runs started by run_workflow (mcp_tasks.py).
            handler = {"tasks/get": mcp_tasks.get, "tasks/result": mcp_tasks.result, "tasks/cancel": mcp_tasks.cancel}[method]
            try:
                return mcp_result(rid, await run_in_threadpool(handler, front, params))
            except mcp_tasks.TaskError as exc:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": exc.code, "message": exc.message}}
        if method in ("resources/list", "resources/templates/list", "prompts/list"):
            # 11-10: clients probe these at start-up; this server offers tools only, so the lists are empty.
            return mcp_result(rid, {{"resources/list": "resources", "resources/templates/list": "resourceTemplates",
                                    "prompts/list": "prompts"}[method]: []})
        if method != "tools/call":
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32601, "message": f"Method not found: {method}"}}
        name = params.get("name") if isinstance(params, dict) else None
        if not isinstance(name, str) or not isinstance(params.get('arguments', {}), dict):
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Provide a tool name and object arguments."}}
        args = params.get("arguments") if isinstance(params, dict) and isinstance(params.get("arguments"), dict) else {}
        if isinstance(name, str) and name.startswith("necklace_"):
            from . import necklace_surface
            if name == "necklace_details":
                found = necklace_surface.details(str(args.get("slug") or ""), front.base(request))
                if found is None:
                    return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Unknown necklace."}}
                return mcp_result(rid, {"content": [{"type": "text", "text": found[0]}], "structuredContent": found[1], "isError": False})
            answer = await run_in_threadpool(necklace_surface.call, front, name, args, "mcp", front.base(request))
            if answer is not None:
                text, structured, failed = answer
                return mcp_result(rid, {"content": [{"type": "text", "text": text}], "structuredContent": structured, "isError": failed})
        if name == "run_workflow":
            # The public run limit of POST /api/workflows/run applies to MCP runs too.
            if not front.security.allow_probe(front.security.resolve_ip(request), base_limit=20):
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32000, "message": "Workflow execution limit reached."}}
            if "task" in params and not isinstance(params["task"], dict):
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "task must be an object."}}
            try:
                run = await run_in_threadpool(mcp_tasks.start, front, args)
            except mcp_tasks.TaskError as exc:
                return mcp_result(rid, mcp_tasks.refused(exc.message))
            value = mcp_tasks.task_id(run)
            if isinstance(params.get("task"), dict):
                current = await run_in_threadpool(front.workflows.get, run["run_id"])
                return mcp_result(rid, {"task": mcp_tasks.view(value, current)})
            return mcp_result(rid, mcp_tasks.started(value, run))
        if name in ('search', 'find_agents', 'search_workflows'):
            try:
                args = discovery_arguments(args)
            except ValueError as exc:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": str(exc)}}
        token = _token_from(request, args.get("visitor_token"))
        agent_name = ((front.mcp_sessions.get(session or "") or {}).get("name")
                      or (client_meta.get("name") if isinstance(client_meta, dict) else None)
                      or (args.get("name") if isinstance(args.get("name"), str) else None))
        if name=='search' and ('k' in args and (type(args['k']) is not int or args['k']<1)):
            return {'jsonrpc':'2.0','id':rid,'error':{'code':-32602,'message':'k must be a positive integer.'}}
        from .mcp_readonly import TOOLS as READ_TOOLS, lookup as read_catalog
        if name in READ_TOOLS:
            try:
                reply=await run_in_threadpool(read_catalog,front,name,args,token)
            except ValueError:
                return {'jsonrpc':'2.0','id':rid,'error':{'code':-32602,'message':'Provide a valid task and protocol selection.'}}
            reply=await run_in_threadpool(front.public_reply,reply)
            structured={'intent':reply.intent,'suggested_replies':reply.suggested,'visitor':None,
                        **reply.data,'conversation_recorded':False}
            return mcp_result(rid,{'content':[{'type':'text','text':reply.text}],
                                  'structuredContent':structured,'isError':reply.data.get('status')=='task_context_required'})
        message, data = "", {}
        if name == "hello":
            message = ""
        elif name == "chat":
            message = str(args.get("message") or "")
        elif name == 'check_agent':
            from .agent_check import CheckError, check
            try:
                found = await run_in_threadpool(check, front.store, args.get('url'))
            except CheckError as error:
                return {'jsonrpc': '2.0', 'id': rid, 'error': {'code': -32602, 'message': str(error)}}
            return mcp_result(rid, {'content': [{'type': 'text', 'text': found['message']}],
                                    'structuredContent': found, 'isError': False})
        elif name == 'workflow_details':
            from .workflow_discovery import published_detail
            template_id = args.get('template_id')
            if type(template_id) is not int or not 0 < template_id < 2**31:
                return {'jsonrpc': '2.0', 'id': rid, 'error': {'code': -32602, 'message': 'A positive integer template_id is required.'}}
            workflow = await run_in_threadpool(published_detail, front.store, template_id, runtime=front.workflows)
            return mcp_result(rid, {'content': [{'type': 'text', 'text':
                'Review the current published inputs before running.' if workflow else 'Published workflow not found.'}],
                'structuredContent': {'workflow': workflow, 'status': 'found' if workflow else 'not_found'},
                'isError': workflow is None})
        elif name == "subscribe":
            from . import traffic as day_traffic
            day_traffic.recorder().note('hidden_tool|subscribe')   # still answered, no longer listed (PM 11-14 04:5x)
            data = {"intent": "contact", "contact": {"type": args.get("contact_type") or "webhook", "url": str(args.get("contact_url") or "")}}
        elif name == "verify_contact":
            data = {"intent": "verify", "code": str(args.get("code") or "")}
        elif name == "call":
            if edge_mode and edge_mode['mode']=='prepare':
                # An unsupported/disabled profile stays on the original ingress
                # before creating a visitor or changing account authentication.
                from ..edge_gateway.native import credential_input
                from ..owned_data_agents.dispatch import is_owned
                requested_id=args.get('resource_id')
                requested=(await run_in_threadpool(front.store.resource,requested_id)) if type(requested_id) is int else None
                if (not service.config.direct_result_delivery or not service.config.native_node_delivery
                        or not requested or is_owned(requested) or requested.get('kind')!='mcp'
                        or requested.get('price_usdc') or args.get('payment')
                        or credential_input(args.get('arguments',{}))):
                    return JSONResponse({'backend':'origin'},headers={'Cache-Control':'private, no-store'})
            v = await run_in_threadpool(front.identify, request, "mcp", token, agent_name, create=True)
            rid_val = args.get("resource_id")
            # North star funnel (11-12 PM): an in-session 'call' is an execution like a gateway tools/call.
            request.scope['traffic_gateway'] = {'step': 'execute', 'ok': False, 'rid': rid_val if type(rid_val) is int else None}
            tool_val = str(args.get("tool") or "")
            call_args = args.get("arguments") if isinstance(args.get("arguments"), dict) else {}
            task_str = str(args.get("task") or "")
            authenticated = front.book.by_token(token)
            account_id = authenticated.id if authenticated else None
            if args.get("account_id") and args["account_id"] != account_id:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Account access denied. Use your visitor token and own account."}}
            payment_info = args.get("payment") if isinstance(args.get("payment"), dict) else None

            if type(rid_val) is not int or not 0<rid_val<2**31 or not tool_val:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "resource_id (int) and tool (string) are required."}}
            bound_resource = front.store.resource(rid_val)
            if not bound_resource:
                return mcp_result(rid, {"content": [{"type": "text", "text": f"Resource {rid_val} not found."}],
                    "structuredContent": {"intent": "call", "ok": False, "error": "Resource not found.", "resource_id": rid_val, "visitor": front.visitor_info(v)}, "isError": True})

            from ..edge_gateway.machine import execute as execute_ticket
            if edge_mode and edge_mode['mode'] == 'prepare':
                from ..edge_gateway.result_transport import available
                if not service.config.direct_result_delivery or not available(front.store):
                    return JSONResponse({'backend':'origin','visitor':front.visitor_info(v)},headers={'Cache-Control':'private, no-store'})
                plan = await run_in_threadpool(execute_ticket, front, rid_val, tool_val, call_args,
                    principal=v.id, idempotency_key=args.get('idempotency_key'), payment=payment_info, prepare_only=True)
                if plan is None:
                    return JSONResponse({'backend':'origin','visitor':front.visitor_info(v)},headers={'Cache-Control':'private, no-store'})
                if plan.get('_edge_plan'):
                    return JSONResponse({**plan,'visitor':front.visitor_info(v)},headers={'Cache-Control':'private, no-store'})
                return mcp_result(rid, {'content':[{'type':'text','text':'The execution is unavailable. Keep this request paused for review.'}],
                    'structuredContent':{'intent':'call','ok':False,'execution':plan,'visitor':front.visitor_info(v)}, 'isError':True})
            ok_val, exec_res, reply_text, structured = await run_admitted_call(
                request, v, rid_val, tool_val, call_args, task_str=task_str, account_id=account_id,
                payment_info=payment_info, idempotency_key=args.get('idempotency_key'), edge_mode=edge_mode,
                service=getattr(front, 'edge_gateway', None))  # what /mcp binds to `service` in edge mode
            answer = mcp_result(rid, {"content": [{"type": "text", "text": reply_text}], "structuredContent": structured, "isError": not bool(ok_val)})
            if edge_mode and edge_mode['mode']=='result' and ok_val:
                return JSONResponse(answer, headers={'X-Edge-Result-Run':edge_mode['run_id']})
            return answer
        elif name == "credit":
            if set(args)-{"action","account_id","visitor_token"} or args.get("action","balance")!="balance":
                return {"jsonrpc":"2.0","id":rid,"error":{"code":-32602,"message":"Credit top-ups are being prepared. Use action balance."}}
            authenticated = front.book.by_token(token)
            if authenticated is None:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "A valid visitor token is required for account access."}}
            v = authenticated
            acc_id = v.id
            if args.get("account_id") and args["account_id"] != acc_id:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Account access denied."}}
            action = str(args.get("action") or "balance")
            if action != "balance":
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Credits require verified settlement. Public deposits are unavailable."}}
            try:
                bal = await run_in_threadpool(front.clearinghouse.balance, acc_id)
            except Exception:
                logging.getLogger(__name__).warning("Credit balance lookup is unavailable.")
                return {"jsonrpc":"2.0","id":rid,"error":{"code":-32603,
                    "message":"Credit balance is temporarily unavailable.",
                    "data":{"error_code":"CREDIT_BALANCE_UNAVAILABLE","retryable":True}}}
            reply_text = f"Credit account '{acc_id}': balance {bal['balance']} micro-USDC, held in escrow {bal['held']}, available {bal['available']}."

            structured = {
                "intent": "credit",
                "action": action,
                "account_id": acc_id,
                "credits": bal,
                "visitor": front.visitor_info(v) if v else None,
            }
            return mcp_result(rid, {"content": [{"type": "text", "text": reply_text}], "structuredContent": structured, "isError": False})
        elif name == "adapt_rest":
            v = await run_in_threadpool(front.identify, request, "mcp", token, agent_name, create=True)
            spec_url = args.get("spec_url")
            spec_obj = args.get("spec")
            base_url = args.get("base_url")
            action = str(args.get("action") or "list_tools")

            if not spec_url and not spec_obj:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Either 'spec_url' or 'spec' is required."}}

            adapter_http = front.proxy._client(public=True)
            try:
                if spec_url:
                    p_url = urlparse(str(spec_url))
                    if p_url.scheme not in ("http", "https") or not p_url.hostname:
                        return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "spec_url must be an http(s) URL."}}
                    from .http_security import validate_public_url
                    from ..broker.discovery import DiscoveryError
                    try:
                        await run_in_threadpool(validate_public_url, str(spec_url))
                    except DiscoveryError as exc:
                        adapter_http.close()
                        # Tell a blocked internal address apart from an unreachable public one.
                        import ipaddress
                        host = p_url.hostname.strip('[]')
                        try:
                            internal = not ipaddress.ip_address(host.split('%')[0]).is_global
                        except ValueError:
                            internal = host == 'localhost' or host.endswith(('.localhost', '.local', '.internal'))
                        message = ("Private or internal addresses are not allowed."
                                   if internal or "Private or internal" in str(exc)
                                   else "spec_url must be a reachable public http(s) URL without credentials.")
                        return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": message}}
                    adapter = await run_in_threadpool(OpenApiAdapter.from_url, str(spec_url), base_url, False, http=adapter_http)
                else:
                    adapter = OpenApiAdapter(spec_obj, base_url, allow_private=False, http=adapter_http)
            except Exception:
                adapter_http.close()
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32603, "message": "Failed to parse or reach OpenAPI specification."}}

            try:
                if action == "list_tools":
                    tools_list = public_metadata(adapter.tools)
                    tool_names = [f"- {t['name']}: {t['description']}" for t in tools_list]
                    reply_text = f"Adapted {len(tools_list)} MCP tools from OpenAPI spec:\n" + "\n".join(tool_names[:15])
                    structured = {
                        "intent": "adapt_rest",
                        "action": "list_tools",
                        "tools_count": len(tools_list),
                        "tools": tools_list,
                        "visitor": front.visitor_info(v) if v else None,
                    }
                    return mcp_result(rid, {"content": [{"type": "text", "text": reply_text}], "structuredContent": structured, "isError": False})
                elif action == "call":
                    t_name = str(args.get("tool") or "")
                    t_args = args.get("arguments") if isinstance(args.get("arguments"), dict) else {}
                    if not t_name:
                        return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "'tool' name is required when action='call'."}}
                    call_res = public_metadata(await run_in_threadpool(adapter.execute, t_name, t_args))
                    reply_text = f"REST endpoint '{t_name}' executed ({call_res.get('latency_ms', 0)}ms):\n{str(call_res.get('sample_output', ''))[:500]}"
                    structured = {
                        "intent": "adapt_rest",
                        "action": "call",
                        "tool": t_name,
                        "execution": call_res,
                        "visitor": front.visitor_info(v) if v else None,
                    }
                    return mcp_result(rid, {"content": [{"type": "text", "text": reply_text}], "structuredContent": structured, "isError": not call_res.get("ok")})
                else:
                    return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": "Unsupported adapt_rest action."}}
            finally:
                adapter.close()
        elif name == "report":
            from .recovery import validate_report, report_outcome
            try:
                validate_report(args)
            except ValueError as exc:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": str(exc)}}
            from .feedback import LIMITER, MCP_PER_HOUR
            if not LIMITER.allow(front.security.resolve_ip(request), args['resource_id'], MCP_PER_HOUR, False):
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32029, "message": "Too many reports from this client. Try again later."}}
            v = await run_in_threadpool(front.identify, request, "mcp", token, agent_name, create=True)
            try:
                value = await run_in_threadpool(report_outcome, front, v, args)
            except ValueError as exc:
                return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602, "message": str(exc)}}
            reply = await run_in_threadpool(front.public_reply, Reply('Outcome recorded. Review alternatives before authorizing a new call.', 'report', value))
            structured = {**reply.data, "visitor": front.visitor_info(v) if v else None}
            return mcp_result(rid, {"content": [{"type": "text", "text": reply.text}], "structuredContent": structured, "isError": False})
        else:
            return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32602,
                "message": f"Unknown tool: {name}. Use tools/list to see the available tools: " + ", ".join(tool["name"] for tool in TOOLS) + "."}}
        v, reply = await run_in_threadpool(front.chat, request, "mcp", message, data, token, agent_name)
        reply=await run_in_threadpool(front.public_reply, reply)
        structured = {"intent": reply.intent, "suggested_replies": reply.suggested, "visitor": front.visitor_info(v), **reply.data}
        return mcp_result(rid, {"content": [{"type": "text", "text": reply.text}], "structuredContent": structured, "isError": False})

    app.include_router(router)
    from .growth_pages import growth_router
    app.include_router(growth_router(front.store))
    from .necklace_surface import necklace_router  # 11-14 PM: public surface of judged necklaces (read-only)
    app.include_router(necklace_router())
    from .feedback import feedback_router
    app.include_router(feedback_router(front))
    from ..agent_access.service import router_for as adoption_router
    app.include_router(adoption_router(front, customer_enabled=workspace_access_enabled))
    from .pearl_view import install as install_pearl_view
    install_pearl_view(app, front, workspace_access_enabled=workspace_access_enabled, workspace_link_enabled=workspace_link_enabled)
    from .managed_gateway import gateway_router
    app.include_router(gateway_router(front, read_json_object))
    from ..edge_gateway.router import install as install_edge_gateway
    install_edge_gateway(app, front)
    from ..workflow_apps import workflow_apps_router
    app.include_router(workflow_apps_router(front))
    from ..workspace_platform import public_router_for as workspace_public_router
    app.include_router(workspace_public_router(front, workspace_access_enabled=workspace_access_enabled))
    from ..first_party_guides import router_for as public_guides_router
    app.include_router(public_guides_router(enabled=first_party_guides_enabled))
    from ..ad_coin.api import router_for as ad_coin_router
    from .workflow_discovery import published_detail as _published_workflow
    from ..ad_coin.private_workflows import (customer_identity_for as _ad_coin_customer_identity,
        reader_for as _ad_coin_private_reader, run_reader_for as _ad_coin_private_runs)
    app.include_router(ad_coin_router(store=front.store, workflow_reader=lambda template_id: _published_workflow(
        front.store, template_id, runtime=front.workflows),
        private_flow_reader=_ad_coin_private_reader(front, workspace_access_enabled),
        customer_identity=_ad_coin_customer_identity(front, workspace_access_enabled),
        private_run_reader=_ad_coin_private_runs(front, workspace_access_enabled)))  # AD_COIN_ENABLED off by default: no routes, test mode only
    from os import environ as _environ
    if _environ.get('AD_COIN_V2_ENABLED', '0') in ('1', 'true', 'True'):  # v2 is off by default; imported only when on
        from ..ad_coin.v2.live_service import is_v2_enabled, create_live_ad_coin_v2_router
        if is_v2_enabled():
            app.include_router(create_live_ad_coin_v2_router(
                include_workspace=True, app_store=front.store,
                customer_identity=_ad_coin_customer_identity(front, workspace_access_enabled)))  # site sign-in bridge
    from .idempotency import Idempotency, MemoryBackend, RedisBackend

    def idempotency_caller(scope, headers):
        # The signed-in session, else the visitor token, else the resolved client address.
        from starlette.requests import Request as ScopeRequest
        session = ScopeRequest(scope).cookies.get('__Host-ac_customer_session')
        if session:
            return 'session:' + session
        if headers.get('x-visitor-token'):
            return 'visitor:' + headers['x-visitor-token']
        return 'address:' + front.security.resolve_ip(ScopeRequest(scope))

    app.add_middleware(Idempotency, backend=RedisBackend(RedisHub.get_instance(), MemoryBackend()), scope_of=idempotency_caller,
                       prefix=_redis_cache_prefix(front.store))
    from .agent_http import AgentHTTP, trusted_origins
    app.add_middleware(AgentHTTP, origins=trusted_origins(front.public_url or 'https://agentconcierge.biz'),
                       security_headers=SECURITY_HEADERS)
    from .public_http_contract import PublicHTTPContract, PublicDocumentHEAD
    app.add_middleware(PublicHTTPContract)
    from .request_timing import RequestTiming
    app.add_middleware(RequestTiming)
    from .execution_errors import QAMark
    app.add_middleware(QAMark)
    app.add_middleware(GZipMiddleware, minimum_size=500)
    app.add_middleware(PublicDocumentHEAD)
    from .web_bot_auth import WebBotAuth
    app.add_middleware(WebBotAuth, origin=front.public_url or 'https://agentconcierge.biz')
    from .public_http_contract import SharedCacheCookieGuard
    app.add_middleware(SharedCacheCookieGuard)  # outermost: sees the final headers
    from .public_api_schema import install as install_public_schema
    install_public_schema(app)
    return app
